def write_doc_15(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """What the starting valuation predicts, and what it does to a lifetime."""
    predictive = frames["predictive"]
    buckets = frames["buckets"]
    advantage = frames["advantage"]
    distribution = frames["distribution"]
    position = notes["position"]
    meta = notes["meta"]
    gamma = float(cfg["utility"]["baseline_risk_aversion"])
    column = f"cec_crra_gamma{gamma:g}"

    predictive_tbl = md_table(_compact(
        _pct(predictive, ["forward_return_expensive", "forward_return_cheap",
                          "gap"]),
        ["horizon_years", "observations", "correlation",
         "forward_return_expensive", "forward_return_cheap", "gap"],
        {"horizon_years": "Horizon (years)", "observations": "Observations",
         "correlation": "Correlation", "forward_return_expensive":
             "Started expensive (%)", "forward_return_cheap":
             "Started cheap (%)", "gap": "Gap (pp)"}),
        floatfmt="{:.2f}")
    advantage_tbl = md_table(_compact(
        _pct(advantage, ["challenger_ruin", "incumbent_ruin"]),
        ["bucket", "n_paths", "challenger_cec", "incumbent_cec",
         "advantage_pct", "challenger_ruin", "incumbent_ruin"],
        {"bucket": "Started", "n_paths": "Paths",
         "challenger_cec": "All-equity CEC", "incumbent_cec": "Glide-path CEC",
         "advantage_pct": "Advantage (%)",
         "challenger_ruin": "All-equity ruin (%)",
         "incumbent_ruin": "Glide-path ruin (%)"}),
        floatfmt="{:.3f}")
    bucket_tbl = md_table(_compact(
        _pct(buckets, ["prob_ruin"]),
        ["bucket", "label", "n_paths", column, "prob_ruin",
         "median_retirement_consumption", "p5_retirement_consumption"],
        {"bucket": "Started", "label": "Strategy", "n_paths": "Paths",
         column: f"CEC (gamma={gamma:g})", "prob_ruin": "P(ruin) (%)",
         "median_retirement_consumption": "Median retirement consumption",
         "p5_retirement_consumption": "5th percentile"}),
        floatfmt="{:.3f}")

    boundaries = frames.get("boundaries")
    leak = notes.get("leak", {})
    hind = notes.get("hindsight_meta", {})
    if boundaries is not None and len(boundaries):
        decades = boundaries[boundaries["year"] % 10 == 0]
        if decades.empty:
            decades = boundaries
        boundaries_tbl = md_table(_compact(
            _pct(decades, ["cut_expensive_middling", "cut_middling_cheap"]),
            ["year", "prior_country_years", "cut_expensive_middling",
             "cut_middling_cheap"],
            {"year": "Lifetime begins",
             "prior_country_years": "Country-years of history",
             "cut_expensive_middling": "Expensive / middling (%)",
             "cut_middling_cheap": "Middling / cheap (%)"}),
            floatfmt="{:.2f}")
        pooled = ", ".join(f"{c:.2%}" for c in hind.get("cuts", []))
        agreement = float(leak.get("agreement_pct", float("nan")))
        if agreement > 95.0:
            leak_verdict = (
                f"and it turns out to have been worth little: the two "
                f"labellings agree on {agreement:.1f}% of the lifetimes both "
                f"can classify, so only "
                f"{int(leak.get('reassigned', 0)):,} change bucket.")
        elif agreement > 80.0:
            leak_verdict = (
                f"and it was worth something: the two labellings agree on "
                f"{agreement:.1f}% of the lifetimes both can classify, so "
                f"{int(leak.get('reassigned', 0)):,} of "
                f"{int(leak.get('compared', 0)):,} were in the wrong bucket "
                "under the pooled boundaries.")
        else:
            leak_verdict = (
                f"**and it was worth a great deal.** The two labellings agree "
                f"on only {agreement:.1f}% of the lifetimes both can "
                f"classify: {int(leak.get('reassigned', 0)):,} of "
                f"{int(leak.get('compared', 0)):,} sat in the wrong bucket "
                "under the pooled boundaries, which is enough to have changed "
                "what the conditioning appeared to show.")
        # The buckets will not come out balanced, and the reason is a result
        # rather than a defect. Classify it from the counts.
        counts = list(meta.get("counts", []))
        total_classified = max(sum(counts), 1)
        shares = [c / total_classified for c in counts]
        skewed = max(shares) > 0.40 if shares else False
        biggest = list(meta.get("labels", []))[int(np.argmax(shares))] \
            if shares else ""
        if skewed:
            balance_note = (
                f"One consequence is worth stating plainly, because it looks "
                f"like a bug and is not. The buckets do **not** come out "
                f"balanced: {shares[0]:.0%} of classified lifetimes land in "
                f"*{list(meta['labels'])[0].lower()}* against "
                f"{shares[-1]:.0%} in *{list(meta['labels'])[-1].lower()}*. "
                "Terciles of a fixed sample are balanced by construction; "
                "terciles of an expanding one are not. Yields fell across "
                "this panel, so a lifetime drawn in year `t` typically starts "
                "at a yield below the average of everything before `t`, and "
                "is therefore expensive *relative to its own history*. An "
                "investor applying this rule in real time would have "
                "concluded 'dear versus history' most of the time, for over "
                "a century, while yields went on falling. That is the "
                "difference between a signal fitted to a sample and one a "
                "person could have run, and it is the reason the correction "
                "was worth making.")
        else:
            balance_note = (
                f"The buckets come out close to balanced -- "
                f"{shares[0]:.0%} / {shares[len(shares)//2]:.0%} / "
                f"{shares[-1]:.0%} -- which is not guaranteed once the "
                "boundaries move, and means the drift in yields over the "
                "panel was mild enough not to tip the classification.")

        first_year = notes.get("first_usable_year")
        boundaries_section = f"""## 5. Which bucket, on what an investor could know

The yield above uses no future data. The *boundaries* are a second and
separate question, and the obvious way to draw them gets it wrong: taking
terciles of the whole panel at once puts the cut-points at {pooled}, so a
lifetime beginning in 1910 is called cheap or dear against a threshold that
already knows what happened in 2020. Nobody in 1910 could have known which
tercile they were in.

So the boundaries are computed recursively instead. A lifetime beginning in
year `t` is ranked against every country-year strictly before `t` -- the
distribution its own investor could have seen. The boundaries therefore move
as history accumulates:

{boundaries_tbl}

They move a long way. Early cohorts faced higher yields, so ranking them
against the whole sample -- dragged down by the low-yield modern era -- makes
them look cheaper than they could possibly have known themselves to be.

This costs coverage. Lifetimes beginning before enough history had
accumulated cannot be classified at all, and are excluded rather than
assigned to the nearest bucket: the study can label
{float(meta.get('classified_pct', float('nan'))):.1f}% of lifetimes, those
beginning in {first_year} or later. That is the price of a statistic a reader
could actually have computed at the time.

The difference between the two labellings is the size of the error,
{leak_verdict}

{balance_note}

"""
    else:
        boundaries_section = ""

    sleeve = frames.get("sleeve")
    sleeve_notes = notes.get("sleeve", {})
    if sleeve is not None and len(sleeve):
        agree = float(sleeve_notes.get("agreement_pct", float("nan")))
        corr = float(sleeve_notes.get("correlation", float("nan")))
        sleeve_tbl = md_table(_compact(
            _pct(sleeve, ["cut_low", "cut_high"]),
            list(sleeve.columns),
            {"sleeve": "Sleeve statistic", "cut_low": "Lower cut (%)",
             "cut_high": "Upper cut (%)"}), floatfmt="{:.2f}")
        if agree > 90.0:
            sleeve_verdict = (
                f"The choice barely matters: the two rank lifetimes almost "
                f"identically (correlation {corr:.3f}) and "
                f"{agree:.1f}% of them land in the same bucket either way, so "
                f"the {int(sleeve_notes.get('reassigned', 0)):,} that move do "
                f"not change any conclusion below.")
        elif agree > 75.0:
            sleeve_verdict = (
                f"The choice moves a meaningful minority of lifetimes: the two "
                f"correlate at {corr:.3f} and agree on {agree:.1f}% of "
                f"bucket assignments, so "
                f"{int(sleeve_notes.get('reassigned', 0)):,} lifetimes are "
                f"classified differently. The results below use the mean; a "
                f"reader who prefers the median should treat the bucket "
                f"boundaries as approximate.")
        else:
            sleeve_verdict = (
                f"**The choice matters.** The two statistics agree on only "
                f"{agree:.1f}% of bucket assignments (correlation "
                f"{corr:.3f}), which is low enough that the construction "
                f"argument above is carrying real weight rather than settling "
                f"a distinction without a difference.")
        sleeve_section = f"""### 4.1 Mean or median across the sleeve?

The international leg holds equal money in every other market with data that
year. The dividend yield of an equally weighted portfolio is the plain mean of
its constituents' yields, so the mean is what the leg's own construction
implies. The median is the natural alternative -- it resists a single market
trading at a distressed yield -- and the argument for the mean is an argument,
not a measurement. So here is the measurement.

{sleeve_tbl}

{sleeve_verdict}
"""
    else:
        sleeve_section = ""

    def _edge(v: float) -> str:
        return "-" if not np.isfinite(v) else f"{v:.2%}"

    distribution_tbl = md_table(_compact(
        distribution.assign(
            yield_floor=distribution["yield_floor"].map(_edge),
            yield_ceiling=distribution["yield_ceiling"].map(_edge)),
        ["bucket", "n_paths", "yield_floor", "yield_ceiling"],
        {"bucket": "Started", "n_paths": "Paths",
         "yield_floor": "Yield from", "yield_ceiling": "Yield to"}))
    distribution_tbl = (
        "Counts and boundaries below are the whole-panel (hindsight) split, "
        "shown for orientation only:\n\n" + distribution_tbl)

    # Every verdict below is classified from the table it describes; none of
    # them is asserted, because any of them could come out the other way on a
    # rebuild and the prose has to survive that.
    by_horizon = predictive.sort_values("horizon_years")
    short_corr = float(by_horizon["correlation"].iloc[0])
    long_corr = float(by_horizon["correlation"].iloc[-1])
    long_horizon = int(by_horizon["horizon_years"].iloc[-1])
    long_gap = float(by_horizon["gap"].iloc[-1])
    strengthens = long_corr > short_corr
    monotone = bool(by_horizon["correlation"].is_monotonic_increasing)
    predicts = bool((by_horizon["gap"] > 0).all())
    multiple = float((1.0 + long_gap) ** long_horizon)

    if not predicts:
        verdict_3 = (
            "No -- the cheap third does not out-return the dear third at "
            "every horizon, so the conditioning below separates lifetimes "
            "that are not actually different in expectation.")
    elif strengthens and monotone:
        verdict_3 = (
            "Yes, and monotonically more strongly the longer the horizon -- "
            "the signature of valuation mean reversion rather than of noise.")
    elif strengthens:
        verdict_3 = (
            "Yes, and more strongly over long horizons than short ones, "
            "though not monotonically -- the signature of valuation mean "
            "reversion rather than of noise.")
    else:
        verdict_3 = (
            "Yes at every horizon, but the relationship does not strengthen "
            "with horizon here, so read it as a level effect rather than as "
            "mean reversion.")

    lead = advantage.set_index("bucket")["advantage_pct"] if len(advantage) \
        else pd.Series(dtype=float)
    holds = bool((lead > 0).all()) if len(lead) else False
    spread = float(lead.max() - lead.min()) if len(lead) else float("nan")
    dearest, cheapest = (lead.index[0], lead.index[-1]) if len(lead) else ("", "")

    # Does starting expensive actually cost the investor anything? Read the
    # headline strategy's own numbers in the dearest and cheapest buckets
    # rather than assuming the sign.
    headline = buckets[buckets["strategy"] == "balanced_all_equity"]
    headline = headline.set_index("bucket") if len(headline) else headline
    have_ends = bool(len(headline)) and dearest in headline.index \
        and cheapest in headline.index
    if have_ends:
        wealth_dear = float(headline.loc[dearest, "median_wealth_at_retirement"])
        wealth_cheap = float(headline.loc[cheapest, "median_wealth_at_retirement"])
        ruin_dear = float(headline.loc[dearest, "prob_ruin"])
        ruin_cheap = float(headline.loc[cheapest, "prob_ruin"])
        wealth_gap = (wealth_dear / wealth_cheap - 1.0) * 100.0
        ruin_gap = (ruin_dear - ruin_cheap) * 100.0
        costly = wealth_dear < wealth_cheap and ruin_dear > ruin_cheap
        if costly:
            verdict_5 = (
                f"A lifetime begun in the {dearest.lower()} bucket reaches "
                f"retirement with {abs(wealth_gap):.0f}% less median wealth "
                f"than one begun in the {cheapest.lower()} bucket and runs out "
                f"of money {abs(ruin_gap):.1f} percentage points more often "
                "under the same withdrawal rule, so it has less room for the "
                "four-percent convention than the unconditional averages "
                "elsewhere in this project suggest.")
        elif wealth_dear < wealth_cheap:
            verdict_5 = (
                f"A lifetime begun in the {dearest.lower()} bucket reaches "
                f"retirement with {abs(wealth_gap):.0f}% less median wealth "
                f"than one begun in the {cheapest.lower()} bucket, though its "
                "ruin probability is not correspondingly higher -- the "
                "spending rule absorbs part of the shortfall.")
        else:
            verdict_5 = (
                "Starting expensive does not measurably cost this investor: "
                f"median wealth at retirement is {abs(wealth_gap):.0f}% "
                f"{'higher' if wealth_gap > 0 else 'lower'} in the "
                f"{dearest.lower()} bucket than in the {cheapest.lower()} one. "
                "The first block is one decade of a sixty-eight-year chain, "
                "and at this sample size that is what the dilution looks "
                "like.")
    else:
        verdict_5 = (
            "The buckets do not carry the headline strategy, so the effect on "
            "wealth and ruin is not reported here.")

    intro = _header(
        "15 - Starting Valuation",
        "What the market costs when a lifetime begins, and how much of the "
        "answer depends on it.",
    )

    body = f"""
## 1. The assumption this relaxes

The bootstrap of `02_multicountry_block_bootstrap.md` draws calendar windows
without regard to how expensive equities were when the window opened. A
lifetime that begins at a market peak is therefore statistically identical to
one that begins at a trough.

That is a strong assumption and an unrealistic one. It is also the assumption a
reader is least able to accept, because they know what today's market costs and
the model does not.

## 2. The observable, and why it is not the obvious one

The workbook records `eq_dp`, a dividend *return*: the dividend paid during
year `t` over the price at the start of it. Conditioning on that would leak,
because the numerator is unknown until the year is over. What an investor
standing at the start of year `t` can actually see is the trailing yield on the
current price:

```
y_(t-1) = D_(t-1) / P_(t-1) = eq_dp_(t-1) / (1 + eq_capgain_(t-1))
```

Both terms are last year's, so the value is fully formed before the year being
predicted begins.

**This is checked structurally rather than argued.** Correlations cannot
establish it: a yield built from the current year's dividend would still
predict the current year's return, and a correctly lagged one still correlates
with the *previous* year's return, because a bad year lowers the price in the
denominator. Both are expected and neither separates a leak from a signal. So
the test overwrites everything the workbook records for a probe year, rebuilds
the series, and confirms the row for that year did not move --
{"which it does not, at all " + str(len(notes["probe_years"])) + " probe years spread across the panel" if notes["leak_free"] else "**which it does, and the results below cannot be trusted**"}.

## 3. Does it predict anything?

{predictive_tbl}

{verdict_3} Over {long_horizon} years the
correlation is {long_corr:.2f}, against {short_corr:.2f} at
{int(by_horizon['horizon_years'].iloc[0])} year(s), and the third of history
that began cheapest returned {long_gap:.1%} a year more than the third that
began dearest. Compounded over those {long_horizon} years that gap is a
factor of {multiple:.2f} on terminal wealth, which is not a rounding
difference.

## 4. Where a reader starts

{distribution_tbl}

Those boundaries are the ones a reader with the whole panel in front of them
would draw. Section 5 replaces them with the ones an investor could actually
have drawn at the time, which is not the same thing.

**{position['iso']} in {int(position['year'])} carries a blended starting yield
of {float(position['blended_yield']):.2%}, which is the
{float(position['blended_percentile']):.0f}th percentile of this panel.** The
domestic leg alone is {float(position['domestic_yield']):.2%}, against a panel
median of {float(position['panel_median_yield']):.2%}. A reader starting from
that market today is starting more expensively than roughly
{100 - float(position['blended_percentile']):.0f}% of the country-years this
study draws from -- which is precisely why the unconditional average is the
wrong number for them.

{sleeve_section}
{boundaries_section}## 6. What it does to the result

{advantage_tbl}

{"**The ranking survives at every starting valuation.**" if holds else "**The ranking does not survive at every starting valuation, and the exception is reported here rather than buried.**"}
The all-equity portfolio leads the glide path in
{int((lead > 0).sum())} of {len(lead)} buckets. What moves is the *level*: the
advantage spans {spread:.1f} percentage points between the
{dearest.lower()} and {cheapest.lower()} buckets.

{bucket_tbl}

The reading a practitioner should take is not that the allocation question
changes much with valuation -- the spread above is
{spread:.1f} percentage points on an advantage of
{float(lead.mean()):.1f}% -- but what happens to the level.
{verdict_5}

## 7. What this does not do

The conditioning applies to the **first** drawn block only. A lifetime is a
chain of calendar windows and only the first is a starting condition; the rest
are the future, which no investor chooses. So the effect measured here is the
effect of the opening decade's valuation on a 68-year outcome, diluted by
everything that follows. A design that made the whole chain valuation-dependent
would report a larger effect and would be assuming a great deal more.

Nor is the expanding window the only real-time normalisation available. A
rolling window would forget the distant past rather than accumulate it, and
ranking a country against its own history rather than the panel's would drop
the assumption that an investor watches every market. Both are defensible and
both would produce a different split; the expanding panel-wide window is
chosen because it uses the most information that was genuinely available, and
because it is the one whose failure mode -- persistent drift in the boundaries
-- is visible in the table above rather than hidden.

Nor does this speak to timing. The result is conditional on where you start,
not a claim that anyone should wait for a better entry point: the sampler
contains no mechanism for choosing when to begin, and the retirement-timing
study of `09_retirement_timing.md` is the closest this project comes to that
question.

## 7. Figures

{chr(10).join(f"* `{f}`" for f in figures)}

## 8. Reproduction

```bash
python main.py --steps 15
```

Runtime {float(notes['elapsed_seconds']):.0f}s.
"""
    return _write(path, [intro, body])


def write_doc_16(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """Housing as a fifth asset, priced by the cost of holding it."""
    audit = frames["audit"]
    sweep = frames["sweep"]
    raw_sweep = frames.get("raw_sweep")
    age_varying = frames.get("age_varying")
    displacement = frames.get("displacement", pd.DataFrame())
    if len(displacement):
        columns = [c for c in ("holding_cost", "dom_eq", "intl_eq", "bond",
                               "bill", "housing")
                   if c in displacement.columns]
        displacement_tbl = md_table(_compact(
            _pct(displacement, columns),
            columns,
            {"holding_cost": "Holding cost (%)", "housing": "Housing (pp)",
             "dom_eq": "Dom. equity (pp)", "intl_eq": "Intl. equity (pp)",
             "bond": "Bonds (pp)", "bill": "Bills (pp)"}),
            floatfmt="{:.1f}")
        reference = float(displacement["reference_cost"].iloc[0])
        displacement_tbl = (
            f"Read against the dearest case tried ({reference:.0%} a year), "
            "where housing earns whatever the sweep gives it at that price, "
            "each row is the change in the optimal weight as the cost falls "
            "to that row's level:\n\n" + displacement_tbl)
    else:
        displacement_tbl = ""
    break_even = float(notes["break_even"])
    gamma = float(notes["gamma"])

    five = sweep[sweep["investable_set"] == "five assets"].sort_values(
        "holding_cost")
    control = sweep[sweep["investable_set"] == "four assets"]

    audit_tbl = md_table(_compact(
        _pct(audit, ["mean_raw", "mean_desmoothed", "sd_raw", "sd_desmoothed",
                     "equity_mean", "equity_sd"]),
        ["iso", "years_raw", "autocorrelation", "mean_raw", "sd_raw",
         "sd_desmoothed", "sd_ratio", "equity_mean", "equity_sd"],
        {"iso": "Country", "years_raw": "Years",
         "autocorrelation": "Lag-1 autocorr.", "mean_raw": "Mean (%)",
         "sd_raw": "SD published (%)", "sd_desmoothed": "SD de-smoothed (%)",
         "sd_ratio": "Ratio", "equity_mean": "Equity mean (%)",
         "equity_sd": "Equity SD (%)"}),
        floatfmt="{:.2f}")

    sweep_tbl = md_table(_compact(
        _pct(five, ["holding_cost", "mean_dom_eq", "mean_intl_eq", "mean_bond",
                    "mean_bill", "mean_housing"]),
        ["holding_cost", "mean_housing", "mean_dom_eq", "mean_intl_eq",
         "mean_bond", "mean_bill", "cec", "advantage_pct"],
        {"holding_cost": "Holding cost (%)", "mean_housing": "Housing (%)",
         "mean_dom_eq": "Dom. equity (%)", "mean_intl_eq": "Intl. equity (%)",
         "mean_bond": "Bonds (%)", "mean_bill": "Bills (%)",
         "cec": "CEC", "advantage_pct": "Gain over four assets (%)"}),
        floatfmt="{:.2f}")

    # -- verdicts, every one classified from the table above ---------------
    free = five.iloc[0] if len(five) else None
    dearest = five.iloc[-1] if len(five) else None
    wanted_free = bool(free is not None and float(free["mean_housing"]) > 0.01)
    wanted_dearest = bool(dearest is not None
                          and float(dearest["mean_housing"]) > 0.01)

    if not wanted_free:
        verdict = ("**Housing earns no place in the portfolio at any price, "
                   "including free.** The de-smoothed series is dominated by "
                   "what the investor can already hold.")
    elif np.isfinite(break_even):
        verdict = (
            f"**Housing is worth holding below an annual cost of "
            f"{break_even:.1%} and not above it.** At no cost the optimum puts "
            f"{float(free['mean_housing']):.0%} of the portfolio in it, worth "
            f"{float(free['advantage_pct']):.1f}% in certainty-equivalent "
            f"consumption over the best four-asset portfolio on the same "
            f"paths; that gain falls away as the cost rises and reaches zero "
            f"at {break_even:.1%} a year.")
    elif wanted_dearest:
        verdict = (
            f"**Housing survives every cost this sweep tried.** Even at "
            f"{float(dearest['holding_cost']):.0%} a year the optimum still "
            f"holds {float(dearest['mean_housing']):.0%} of it. The break-even "
            "cost is above the top of the grid, so it is not reported: "
            "extrapolating it would be inventing the number the sweep failed "
            "to find.")
    else:
        verdict = ("**Housing enters at low cost and leaves at high cost, but "
                   "the crossing falls between grid points in a way the "
                   "interpolation could not resolve.**")

    # Which asset does housing displace? Compare the free and dearest rows.
    displaced = ""
    if free is not None and dearest is not None:
        moves = {
            "domestic equity": float(free["mean_dom_eq"]) - float(dearest["mean_dom_eq"]),
            "international equity": float(free["mean_intl_eq"]) - float(dearest["mean_intl_eq"]),
            "bonds": float(free["mean_bond"]) - float(dearest["mean_bond"]),
            "bills": float(free["mean_bill"]) - float(dearest["mean_bill"]),
        }
        loser = min(moves, key=moves.get)
        if moves[loser] < -0.01:
            untouched = [name for name, move in moves.items()
                         if abs(move) < 0.01]
            givers = [name for name, move in moves.items() if move < -0.01]
            displaced = (
                f"The weight comes out of **{loser}**, which falls "
                f"{abs(moves[loser]):.0%} of the portfolio between the dearest "
                f"and the free case -- more than any other asset gives up."
                + (f" {_and_list(untouched).capitalize()} "
                   f"{'is' if len(untouched) == 1 else 'are'} untouched at "
                   "every cost. Housing is therefore not substituting for the "
                   "portfolio at large but for its "
                   + ("growth sleeve" if len(givers) > 1 else "single largest "
                      "holding") + ".")
                   if untouched else
                   " The rest of the portfolio absorbs the remainder.")

    # Does the smoothing bias the answer, and in which direction?
    raw_note = "_The comparison against the raw series was not run._"
    if raw_sweep is not None and len(raw_sweep):
        raw_five = raw_sweep[
            raw_sweep["investable_set"] == "five assets"].sort_values(
            "holding_cost")
        raw_break = hs_break_even(raw_five)
        raw_free = float(raw_five.iloc[0]["mean_housing"])
        naive_higher = raw_free > float(free["mean_housing"])
        raw_note = (
            f"Left smoothed, the same search puts {raw_free:.0%} in housing at "
            f"zero cost against {float(free['mean_housing']):.0%} once the "
            f"smoothing is undone"
            + (f", and its break-even cost is {raw_break:.2%} against "
               f"{break_even:.2%}" if np.isfinite(raw_break)
               and np.isfinite(break_even) else "")
            + ". "
            + ("The naive treatment therefore **overstates** the case for "
               "housing, which is the direction the mechanism predicts: "
               "smoothing hides volatility, and hidden volatility looks like "
               "risk-adjusted return."
               if naive_higher else
               "The naive treatment does **not** overstate the case here, "
               "which is worth noting because it is the opposite of what the "
               "mechanism predicts."))

    age_note = "_The constant-mix restriction was not tested._"
    if age_varying is not None and len(age_varying):
        gaps = age_varying.get("housing_difference")
        gains = age_varying.get("cec_gain_pct")
        if gaps is not None and gains is not None:
            worst = float(np.abs(gaps).max())
            best_gain = float(gains.max())
            # The search starts from the constant-mix optimum, so it can only
            # improve on it. A gain that rounds to zero means age-variation
            # found nothing, which is a result about the shape rather than a
            # failure of the search.
            if best_gain <= 0.05:
                age_note = (
                    "Letting the allocation vary with age buys essentially "
                    f"nothing: at most {best_gain:.2f}% more "
                    "certainty-equivalent consumption, from a search that "
                    "began at the constant-mix optimum and could only improve "
                    "on it. The single lifetime-long allocation reported above "
                    "is, to the resolution of this search, the answer.")
            elif worst < 0.10 and best_gain < 1.0:
                age_note = (
                    f"Letting the allocation vary with age moves the mean "
                    f"housing weight by at most {worst:.0%} of the portfolio "
                    f"and buys at most {best_gain:.2f}% more "
                    "certainty-equivalent consumption -- small enough that the "
                    "constant-mix reading above stands.")
            else:
                age_note = (
                    f"Letting the allocation vary with age moves the mean "
                    f"housing weight by up to {worst:.0%} of the portfolio and "
                    f"buys up to {best_gain:.2f}% more certainty-equivalent "
                    "consumption -- large enough that the constant-mix reading "
                    "above should be treated as indicative only.")

            working = age_varying.get("housing_working")
            retired = age_varying.get("housing_retired")
            if working is not None and retired is not None:
                rises = bool((retired.to_numpy() > working.to_numpy()).all())
                falls = bool((retired.to_numpy() < working.to_numpy()).all())
                widest = int(np.argmax(np.abs(retired.to_numpy()
                                              - working.to_numpy())))
                if rises:
                    age_note += (
                        f"\n\nThe shape is worth naming whatever its size. "
                        f"Housing is the one asset in this project whose "
                        f"optimal weight **rises** with age: at a "
                        f"{float(age_varying['holding_cost'].iloc[widest]):.0%} "
                        f"holding cost the solved schedule holds "
                        f"{float(working.iloc[widest]):.0%} of it while working "
                        f"and {float(retired.iloc[widest]):.0%} in retirement. "
                        "That is the opposite of the glide path this project "
                        "spends most of its length arguing against, and it has "
                        "a reading: a retiree drawing on the portfolio wants "
                        "the asset whose volatility is lowest relative to its "
                        "return, and once the smoothing is undone housing is "
                        "still that asset.")
                elif falls:
                    age_note += (
                        f"\n\nThe solved schedule holds **less** housing in "
                        f"retirement than while working -- "
                        f"{float(retired.iloc[widest]):.0%} against "
                        f"{float(working.iloc[widest]):.0%} at the widest "
                        "point -- which is a conventional glide-path shape, in "
                        "an asset the rest of this project does not hold.")

    age_tbl = md_table(_compact(
        _pct(age_varying, ["holding_cost", "mean_housing",
                           "housing_working", "housing_retired",
                           "constant_mix_housing"]),
        ["holding_cost", "mean_housing", "housing_working", "housing_retired",
         "constant_mix_housing", "cec", "cec_gain_pct"],
        {"holding_cost": "Holding cost (%)", "mean_housing": "Housing, mean (%)",
         "housing_working": "While working (%)",
         "housing_retired": "In retirement (%)",
         "constant_mix_housing": "Constant-mix housing (%)",
         "cec": "CEC", "cec_gain_pct": "Gain over constant mix (%)"}),
        floatfmt="{:.2f}") if age_varying is not None and len(age_varying) \
        else "_Not run._"

    moments_d = notes.get("moments_desmoothed", {})
    moments_r = notes.get("moments_raw", {})

    intro = _header(
        "16 - Housing",
        "The fourth asset class the sources measure, priced by what it costs "
        "to hold.",
    )

    body = f"""
## 1. The asset that was left out

The source project measures four asset classes. Three of them -- equity, bonds
and bills -- are the investable set everywhere else in this study. The fourth,
housing, is measured just as carefully across
{int(len(audit))} countries and
{int(audit['years_raw'].sum()):,} country-years, and nothing else here invests
in it.

There are two honest reasons for that, and this section confronts both rather
than repeating them.

**The index is smoothed.** House prices come from transactions and valuations,
not from a continuous auction, so this year's index still carries part of last
year's level. The published series therefore understates the volatility an
owner actually bears, and comparing it with a traded series would flatter it.

**A building costs money to hold.** A share certificate does not. Rates,
insurance, maintenance and management fall on the owner every year whether the
asset rose or fell, and the right number is investor- and
jurisdiction-specific. Rather than pick one, this section sweeps it.

The source builds its housing total return from capital gains plus a rental
yield it describes as net of running costs, so the swept cost is best read as
*additional* to whatever that construction already deducts. If the published
series is in fact grosser than that, the break-even below overstates how much
extra cost housing can bear -- the direction of the error is known even though
its size is not, which is why the whole curve is reported rather than a single
recommended weight.

## 2. Undoing the smoothing

Each country is de-smoothed with its own estimated first-order coefficient --
`r*_t = (r_t - a·r_(t-1)) / (1 - a)` -- because index construction differs by
country, and a pooled coefficient would over-correct the cleanly measured
series and under-correct the rest. A country whose returns are not positively
autocorrelated is left alone: there is nothing to undo.

{audit_tbl}

Pooled across the panel this lifts the standard deviation of real housing
returns from {float(moments_r.get('sd', float('nan'))):.1%} to
{float(moments_d.get('sd', float('nan'))):.1%} while leaving the mean at
{float(moments_d.get('mean', float('nan'))):.1%} -- which is what inverting a
first-order filter should do, since the transformation preserves the mean in
expectation and restores the variance the filter removed.

That leaves housing with an equity-like average return and materially less
volatility than equity, which is precisely why the holding cost has to be taken
seriously rather than assumed away.

## 3. Which country-years the study can use

Housing is recorded for {int(notes['kept_cells']):,} of the
{int(notes['total_cells']):,} country-years the panel otherwise has
({100.0 * int(notes['kept_cells']) / max(int(notes['total_cells']), 1):.0f}%).
The study runs on that intersection. The alternative -- filling the missing
cells -- would mean inventing returns, so instead every asset is drawn from the
same, smaller set of genuinely observed years.

The four-asset control is re-solved on that same restricted panel and against
the same {int(notes['n_paths']):,} lifetimes and the same income draws, so the
restriction cancels out of every comparison below. Its own optimum is
{float(control.iloc[0]['mean_dom_eq']):.0%} domestic equity,
{float(control.iloc[0]['mean_intl_eq']):.0%} international,
{float(control.iloc[0]['mean_bond']):.0%} bonds and
{float(control.iloc[0]['mean_bill']):.0%} bills.

## 4. The sweep

One allocation, held for life, re-solved over the whole five-asset simplex at
each annual holding cost. Common random numbers throughout: the paths, the
income draws and the search are identical across rows, so a difference between
two rows is the holding cost and nothing else.

Housing enters as a **domestic** asset: each simulated investor holds their own
country's housing index, drawn on the same calendar years, countries and blocks
as their equity and bonds. There is no international housing sleeve, because
people buy property where they live, and because the leave-one-out construction
that gives equity a foreign leg has no counterpart a household could actually
execute in bricks.

{sweep_tbl}

{verdict}

{displaced}

{displacement_tbl}

## 5. Is the answer an artefact of the smoothing?

{raw_note}

## 6. Is the answer an artefact of holding one allocation for life?

{age_tbl}

{age_note}

## 7. What this is not

The asset priced here is a **liquid, continuously rebalanced, nationally
diversified claim on the housing stock**, because that is what a national house
price index measures. It is not a house.

A single owner-occupied property is concentrated in one street rather than
spread across a country, cannot be rebalanced, is bought with leverage, carries
transaction costs measured in percent rather than basis points, and pays part of
its return as accommodation rather than cash. Every one of those differences
matters, and none of them is in the numbers above. Read this section as the
price of the *asset class*, not as advice about a mortgage.

Nor does the sweep model the cost as anything but a constant annual percentage
of value. Real costs are lumpy, partly fixed, and correlated with the cycle;
a constant charge is the tractable approximation, not the truth.

## 8. Figures

{chr(10).join(f"* `{f}`" for f in figures)}

## 9. Reproduction

```bash
python main.py --steps 16
```

Runtime {float(notes['elapsed_seconds']):.0f}s at {int(notes['n_paths']):,}
paths, risk aversion {gamma:g}.
"""
    return _write(path, [intro, body])


def hs_break_even(frame: pd.DataFrame) -> float:
    """:func:`src.housing.break_even_cost`, imported lazily for the report."""
    from .housing import break_even_cost
    return break_even_cost(frame)


def write_doc_17(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """How much of the house to borrow, at what age, and at what price."""
    sweep = frames["sweep"]
    schedule = frames["schedule"]
    curve = frames["curve"]
    break_even = float(notes["break_even"])
    option = notes.get("option", {})
    cap = float(notes.get("lvr_cap", 0.80))
    detail = float(notes["detail_spread"])

    working = schedule[schedule["phase"] == "working"]
    retired = schedule[schedule["phase"] == "retired"]
    lvr_work = float(working["lvr"].mean()) if len(working) else float("nan")
    lvr_ret = float(retired["lvr"].mean()) if len(retired) else float("nan")

    sweep_tbl = md_table(_compact(
        _pct(sweep, ["spread", "mean_lvr", "lvr_working", "lvr_retired",
                     "housing_weight", "negative_equity_share"]),
        ["spread", "mean_lvr", "lvr_working", "lvr_retired", "housing_weight",
         "gross_housing_exposure", "gain_vs_unlevered_pct",
         "negative_equity_share"],
        {"spread": "Spread over short rate (%)", "mean_lvr": "Mean LVR (%)",
         "lvr_working": "LVR working (%)", "lvr_retired": "LVR retired (%)",
         "housing_weight": "Housing equity (%)",
         "gross_housing_exposure": "Gross exposure (x net wealth)",
         "gain_vs_unlevered_pct": "Gain over no mortgage (%)",
         "negative_equity_share": "Path-years wiped out (%)"}),
        floatfmt="{:.2f}")

    curve_tbl = md_table(_compact(
        _pct(curve, ["lvr", "negative_equity_share"]),
        ["lvr", "leverage_multiple", "cec", "gain_vs_unlevered_pct",
         "negative_equity_share"],
        {"lvr": "LVR (%)", "leverage_multiple": "Gross exposure per unit",
         "cec": "CEC", "gain_vs_unlevered_pct": "Gain over no mortgage (%)",
         "negative_equity_share": "Path-years wiped out (%)"}),
        floatfmt="{:.3f}")

    decades = schedule[schedule["age"] % 5 == 0]
    if decades.empty:
        decades = schedule
    schedule_tbl = md_table(_compact(
        _pct(decades, ["lvr", "housing_equity_weight"]),
        ["age", "phase", "lvr", "gross_housing_exposure"],
        {"age": "Age", "phase": "Phase", "lvr": "LVR (%)",
         "gross_housing_exposure": "Gross housing (x net wealth)"}),
        floatfmt="{:.2f}")

    # -- the reconciliation against the portfolio-leverage study ----------
    comparison = frames.get("comparison")
    leverage = frames.get("leverage")
    reconciliation_tbl = reconciliation_note = asset_tbl = ""
    if comparison is not None and len(comparison):
        labels = {"housing": "Housing", "dom_eq": "Domestic equity",
                  "intl_eq": "International equity", "bond": "Bonds",
                  "bill": "Bills"}
        shown = comparison.assign(
            asset=comparison["asset"].map(lambda v: labels.get(v, v)))
        asset_tbl = md_table(_compact(
            _pct(shown, ["mean", "sd", "correlation_with_housing"]),
            ["asset", "mean", "sd", "return_per_unit_risk",
             "correlation_with_housing"],
            {"asset": "Asset", "mean": "Mean real (%)", "sd": "s.d. (%)",
             "return_per_unit_risk": "Return per unit of risk",
             "correlation_with_housing": "Correlation with housing (%)"}),
            floatfmt="{:.2f}")
        house = comparison[comparison["asset"] == "housing"].iloc[0]
        intl = comparison[comparison["asset"] == "intl_eq"].iloc[0]
        legs = float(comparison["equity_leg_correlation"].iloc[0])
        better = float(house["return_per_unit_risk"]) > float(
            intl["return_per_unit_risk"])
        reconciliation_note = (
            f"**It is diversification.** Housing's standalone return per unit "
            f"of risk is {float(house['return_per_unit_risk']):.2f} against "
            f"international equity's "
            f"{float(intl['return_per_unit_risk']):.2f} -- "
            + ("better, but not by enough to explain a multiple."
               if better else
               "*worse*, so the gap cannot be a story about housing being the "
               "superior asset.")
            + f" What housing has is a correlation of "
            f"{float(intl['correlation_with_housing']):.2f} with the "
            f"international equity sleeve, where the two equity legs "
            f"correlate at {legs:.2f} with each other. Levering the portfolio "
            f"scales risk the investor already holds; levering one asset "
            f"changes what the portfolio is made of, and here it buys more of "
            f"the holding that moves independently of the rest while tying up "
            f"less capital in it.")
    if leverage is not None and len(leverage):
        best_by_spread = leverage.loc[
            leverage.groupby("spread")["cec"].idxmax()]
        merged = best_by_spread[["spread", "vs_unlevered_pct"]].merge(
            sweep[["spread", "gain_vs_unlevered_pct"]], on="spread",
            how="inner").sort_values("spread")
        if len(merged):
            reconciliation_tbl = md_table(_compact(
                _pct(merged, ["spread"]),
                ["spread", "vs_unlevered_pct", "gain_vs_unlevered_pct"],
                {"spread": "Spread over the real short rate (%)",
                 "vs_unlevered_pct": "Lever the portfolio (%)",
                 "gain_vs_unlevered_pct": "Mortgage the housing sleeve (%)"}),
                floatfmt="{:.2f}")

    # -- verdicts, classified ---------------------------------------------
    best_flat = curve.loc[curve["cec"].idxmax()]
    interior = 0.0 < float(best_flat["lvr"]) < cap - 1e-9
    if float(best_flat["lvr"]) <= 1e-9:
        headline = (
            "**No mortgage is worth taking at this price.** The solved "
            "loan-to-value is zero: the borrowing rate exceeds what the "
            "levered house returns, once the tail risk it adds is priced by a "
            "risk-averse investor.")
    elif interior:
        headline = (
            f"**The answer is an interior one: about "
            f"{float(best_flat['lvr']):.0%} loan-to-value.** Held flat for "
            f"life that is worth "
            f"{float(best_flat['gain_vs_unlevered_pct']):.1f}% in "
            f"certainty-equivalent consumption over the same house owned "
            f"outright. More borrowing is available -- the grid runs to "
            f"{cap:.0%} -- and is not taken, because the extra return does "
            f"not compensate a risk-averse investor for the tail it opens.")
    else:
        solved_cec = float(notes.get("solved_cec", float("nan")))
        solved_mean = float(notes.get("solved_mean_lvr", float("nan")))
        beats = np.isfinite(solved_cec) and solved_cec > float(best_flat["cec"])
        headline = (
            f"**Held flat, the ratio goes to the {cap:.0%} ceiling and would "
            f"go further if allowed.** A single lifetime-long number is "
            f"therefore the constraint rather than an optimum, and this model "
            f"does not price whatever stops real households borrowing more -- "
            f"mortgage insurance, servicing tests, and the concentration risk "
            f"of a single property, none of which are here."
            + (f"\n\nBut a flat ratio is the wrong object. Letting it vary "
               f"with age reaches a higher certainty equivalent "
               f"({solved_cec:.4f} against {float(best_flat['cec']):.4f}) at a "
               f"*lower* average ratio of {solved_mean:.0%}, by borrowing hard "
               f"early and paying down later. The corner above is an artefact "
               f"of forcing one number on a decision that should move; the "
               f"next section is the answer."
               if beats else ""))

    prof = notes.get("profile", {})
    material = int(prof.get("material_ages", 0))
    ages = int(prof.get("ages", 0))
    if ages and material == 0:
        profile_note = (
            f"**None of the age-by-age detail survives that test.** Resetting "
            f"any single age to the schedule's own average costs less than "
            f"{float(prof.get('material_bp', 5)):.0f} basis points. The "
            "jaggedness in the table above is search noise on a flat surface, "
            "and the only defensible reading of this schedule is its level "
            "and its broad slope -- not the value at any particular age.")
    elif ages:
        profile_note = (
            f"**{material} of {ages} ages carry a decision worth more than "
            f"{float(prof.get('material_bp', 5)):.0f} basis points**, the "
            f"largest worth {float(prof.get('max_cost_bp', 0)):.0f}; the "
            f"median age is worth "
            f"{float(prof.get('median_cost_bp', 0)):.0f}. The rest of the "
            "schedule sits on a flat part of the surface, where the search "
            "moves the ratio for free and the plotted line looks more "
            "structured than the evidence supports. Read the level and the "
            "slope; do not read any single age.")
    else:
        profile_note = ""

    declines = lvr_work > lvr_ret
    shape = (
        f"The schedule **declines with age**: {lvr_work:.0%} while working "
        f"against {lvr_ret:.0%} in retirement. That is what households "
        "actually do -- borrow heavily against the first house and pay the "
        "loan down over a career -- and it falls out of the optimisation "
        "rather than being imposed on it. The reason is human capital: a "
        "working investor has decades of future earnings that a mortgage "
        "cannot reach, and that income is what makes the leverage bearable. "
        "It is also the mirror image of the equity glide path this project "
        "spends most of its length arguing against, and the two are "
        "consistent: what should decline with age is the *borrowing*, not "
        "the equity."
        if declines else
        f"The schedule **rises with age**: {lvr_work:.0%} while working "
        f"against {lvr_ret:.0%} in retirement, which is the opposite of what "
        "households do and deserves the suspicion that attaches to any result "
        "that contradicts observed behaviour.")

    if option.get("looks_like_the_option"):
        option_note = (
            f"**One part of the schedule should be discounted.** The final "
            f"{int(option['tail_years'])} years carry an average "
            f"{float(option['lvr_final_years']):.0%} loan-to-value against "
            f"{float(option['lvr_before_that']):.0%} before them -- a lift of "
            f"{float(option['terminal_lift']):.0%} of the property's value. "
            "That is not a preference for housing. It is the limited-liability "
            "floor: an investor who will not live to repay can lever into the "
            "last few years knowing the lender absorbs the downside, and the "
            "model rewards it. A real estate settles its debts before anything "
            "reaches the heirs. Read the working-life and early-retirement "
            "portion of the schedule; discount the tail.")
    else:
        option_note = (
            f"The last {int(option.get('tail_years', 5))} years carry an "
            f"average {float(option.get('lvr_final_years', float('nan'))):.0%} "
            f"loan-to-value against "
            f"{float(option.get('lvr_before_that', float('nan'))):.0%} before "
            "them, so the solver is not visibly exploiting the "
            "limited-liability floor at the end of life -- which it would "
            "have been free to do.")

    if np.isfinite(break_even):
        price_note = (
            f"**Borrowing stops paying at a spread of about "
            f"{break_even:.1%}** over the domestic short rate. Below that the "
            f"optimal loan-to-value is positive and falls as credit gets "
            f"dearer; above it the mortgage earns no place at all.")
    else:
        ordered = sweep.sort_values("spread")
        first, last = ordered.iloc[0], ordered.iloc[-1]
        collapses = float(last["mean_lvr"]) < 0.5 * float(first["mean_lvr"])
        wanted = bool((sweep["mean_lvr"] > 0.01).all())
        if wanted and collapses:
            price_note = (
                f"**The optimal ratio collapses as credit gets dearer** -- "
                f"from {float(first['mean_lvr']):.0%} at a "
                f"{float(first['spread']):.0%} spread to "
                f"{float(last['mean_lvr']):.0%} at "
                f"{float(last['spread']):.0%} -- without quite reaching zero "
                "inside the grid, so no break-even price is reported: "
                "extrapolating it would invent the number the sweep failed to "
                "find. What the table does establish is that the answer is "
                "highly sensitive to the margin, which is the practical "
                "point.")
        elif wanted:
            price_note = (
                "**Borrowing survives every spread this sweep tried**, so the "
                "break-even price is above the top of the grid and is not "
                "reported: extrapolating it would invent the number the sweep "
                "failed to find.")
        else:
            price_note = ("**Borrowing earns no place at any spread tried, "
                          "including a free loan.**")

    intro = _header(
        "17 - The Mortgage",
        "How much of the house to borrow, at what age, and at what price of "
        "credit.",
    )

    body = f"""
## 1. Why leverage belongs here at all

`16_housing.md` prices housing as an asset owned outright. No household owns
it that way. A house is the one asset an ordinary person can borrow
{cap:.0%} against, at a rate close to their own government's, secured on the
thing itself. Leaving that out understates what housing does to a lifetime as
surely as leaving the holding cost out overstates it.

So this section puts the mortgage in, and asks the only two questions that
matter: how much, and when.

## 2. How the loan is modelled

The decision variable is the **loan-to-value ratio**, because that is the
number a lender quotes and a borrower chooses. A property worth `V` funded
with equity `E = (1 - L/V)*V` returns, on that equity,

```
r_E = (r_H - LVR * i) / (1 - LVR)
```

where `r_H` is the real return on the property and `i` the real mortgage rate.
That is the leverage multiple `1/(1 - LVR)` applied to housing alone, so the
arithmetic is the same function the borrowing study of `13_leverage.md` uses
and the two stay consistent.

The rate is the borrower's **own country's** real short rate plus a spread,
drawn on the same block as every other series, so a lifetime that lives
through high real rates pays them. The spread is swept rather than assumed.

Housing is charged a {float(notes['holding_cost']):.0%} annual holding cost
throughout, which is the residue after the source series' own deduction of
maintenance and depreciation: taxes, management, voids and amortised
transaction costs.

Equity is **wiped out, not driven negative**. The levered return is floored at
total loss, which is the non-recourse assumption and the one most favourable
to borrowing. How often it binds is reported below rather than buried.

## 3. How much, at one price

At a {detail:.0%} spread, holding the ratio flat for life:

{curve_tbl}

{headline}

## 4. When

{schedule_tbl}

{shape}

{profile_note}

{option_note}

## 5. At what price of credit

{sweep_tbl}

{price_note}

## 6. Why this differs from `13_leverage.md`

That document concluded borrowing is barely worth doing. This one concludes
borrowing against a house is worth a great deal. Both use the same arithmetic
and the same real bill rate plus a swept spread, so the two have to be
reconciled rather than left side by side.

{reconciliation_tbl}

**It is not the price of credit.** At identical spreads the mortgage is worth
several times what portfolio leverage is worth, so holding the borrowing rate
fixed does not close the gap and cannot be the explanation.

{asset_tbl}

{reconciliation_note}

## 7. What this is not

The schedule is rebalanced annually, like everything else in this project.
For a mortgage that means costlessly redrawing the loan every year to hit a
target ratio. Real mortgages amortise on a fixed schedule, cost several
percent of the property to refinance, and are called on missed payments rather
than on a drifting loan-to-value. **This is the value of the leverage, not a
financing plan.**

Three further gaps are worth naming. The model has no mortgage insurance, so
the {cap:.0%} ceiling is a hard wall rather than a price. It has no tax: in
several countries mortgage interest is deductible and owner-occupied capital
gains are not taxed, both of which would favour borrowing more than this shows.
And it prices a nationally diversified housing index, not a house -- the
concentration risk a single leveraged property carries is precisely what a
mortgage makes dangerous, and none of it is here.

## 8. Figures

{chr(10).join(f"* `{f}`" for f in figures)}

## 9. Reproduction

```bash
python main.py --steps 17
```

Runtime {float(notes['elapsed_seconds']):.0f}s at {int(notes['n_paths']):,}
paths, risk aversion {float(notes['gamma']):g}.
"""
    return _write(path, [intro, body])


#: Display names for the sleeve weighting schemes, so no table prints a bare
#: config key.
_SLEEVE_LABELS: Dict[str, str] = {
    "equal": "Equal-weighted", "gdp": "Real GDP", "pop": "Population",
    "gdp_pc": "GDP per capita", "inverse_vol": "Inverse volatility",
}


def write_doc_18(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """Whether the headline needs an equal-weighted international sleeve."""
    ranking = frames["ranking"]
    moments = frames["moments"]
    conc = frames["concentration"]
    spectrum = frames["spectrum"]
    gamma = float(notes["gamma"])
    found = notes["verdict"]

    schemes = [s for s in found.get("schemes", []) if s in set(ranking.columns)]
    alternatives = [s for s in schemes if s != "equal"]
    n_markets = int(conc["markets"].max())
    ref = spectrum[spectrum["weighting"] == "equal"]
    ref_gap = float(ref["gap_pct"].iloc[0]) if len(ref) else float("nan")
    tightest = spectrum.iloc[0] if len(spectrum) else None
    # Which scheme is kindest to the finding is a question for the data, not
    # an assumption: the equal weighting is the obvious suspect but need not
    # be the answer.
    kindest = spectrum.loc[spectrum["gap_pct"].idxmax()] if len(spectrum) \
        else None
    equal_is_kindest = bool(kindest is not None
                            and str(kindest["weighting"]) == "equal")
    mean_equal_markets = float(ref["effective_markets"].iloc[0]) \
        if len(ref) else float("nan")

    spectrum_tbl = md_table(_compact(
        _pct(spectrum, ["sd"]),
        ["label", "tilts_towards", "effective_markets", "sd",
         "correlation_with_domestic", "gap_pct"],
        {"label": "Weighting", "tilts_towards": "Tilts towards",
         "effective_markets": "Effective markets",
         "sd": "Sleeve SD (%)",
         "correlation_with_domestic": "Corr. with home",
         "gap_pct": "All-intl over 50/50 (%)"}), floatfmt="{:.3f}")

    moments_tbl = md_table(_compact(
        _pct(moments, ["mean", "sd", "correlation_with_domestic"]),
        ["label", "mean", "sd", "return_per_unit_risk",
         "correlation_with_domestic"],
        {"label": "Sleeve", "mean": "Mean (%)", "sd": "SD (%)",
         "return_per_unit_risk": "Return per unit risk",
         "correlation_with_domestic": "Corr. with home market (%)"}),
        floatfmt="{:.3f}")

    ranking_cols = ["label"] + schemes
    ranking_tbl = md_table(_compact(
        ranking, ranking_cols,
        {"label": "Strategy",
         **{s: _SLEEVE_LABELS.get(s, s) for s in schemes}}),
        floatfmt="{:.4f}")

    change_cols = [f"{s}_change_pct" for s in alternatives
                   if f"{s}_change_pct" in ranking.columns]
    change_tbl = md_table(_compact(
        ranking, ["label"] + change_cols,
        {"label": "Strategy",
         **{f"{s}_change_pct": _SLEEVE_LABELS.get(s, s) + " (%)"
            for s in alternatives}}), floatfmt="{:.2f}") \
        if change_cols else "_not computed_"

    decades = conc[(conc["year"] % 30 == 0) & (conc["weighting"] != "equal")]
    conc_tbl = md_table(_compact(
        _pct(decades, ["largest_share"]),
        ["label", "year", "effective_markets", "largest_market",
         "largest_share"],
        {"label": "Weighting", "year": "Year",
         "effective_markets": "Effective markets",
         "largest_market": "Largest", "largest_share": "Largest share (%)"}),
        floatfmt="{:.2f}")

    # -- the verdict, classified rather than asserted ----------------------
    if found["winner_changes"]:
        headline = (
            "**Some weighting changes which strategy wins.** The headline of "
            "this project is a property of how the international leg was "
            "built, and every result that leans on it should be read with "
            "that in mind.")
    elif found["ordering_changes"]:
        headline = (
            "**Some weighting flips the ordering this project diverges on.** "
            "All-international leads the 50/50 split under some constructions "
            "and trails it under others, so the divergence from the "
            "replicated paper is a construction artefact rather than a "
            "finding about the world.")
    else:
        worst = found.get("worst_scheme", "")
        retained = found.get("worst_share_retained", float("nan"))
        headline = (
            f"**The ordering survives every weighting tested.** "
            f"All-international leads the 50/50 split by {ref_gap:+.2f}% on "
            f"the equal-weighted sleeve. The harshest alternative is "
            f"{_SLEEVE_LABELS.get(worst, worst)}, which leaves "
            f"{float(found.get('worst_gap_pct', float('nan'))):+.2f}% -- "
            f"{retained:.0%} of the reference gap. The divergence from the "
            f"replicated paper narrows under a realistic sleeve but does not "
            f"close.")

    # Does the gap track concentration, or what the scheme tilts towards?
    mech = ""
    if len(spectrum) > 2:
        corr = float(np.corrcoef(spectrum["effective_markets"],
                                 spectrum["gap_pct"])[0, 1])
        near = spectrum[spectrum["effective_markets"]
                        >= 0.85 * float(n_markets)]
        spread_near = (float(near["gap_pct"].max())
                       - float(near["gap_pct"].min())) if len(near) > 1 \
            else float("nan")
        full_spread = float(spectrum["gap_pct"].max()) \
            - float(spectrum["gap_pct"].min())
        mech = (
            f"The gap correlates {corr:+.2f} with the effective number of "
            f"markets across the {len(spectrum)} schemes. "
            + (f"The {len(near)} schemes that barely concentrate the sleeve "
               f"({_and_list([str(v) for v in near['label']])}) span only "
               f"{spread_near:.2f} points of gap between them, against "
               f"{full_spread:.2f} across the whole set -- so it is the "
               f"concentration that moves the answer, not the direction of "
               f"the tilt."
               if np.isfinite(spread_near)
               and spread_near < 0.5 * full_spread else
               f"The schemes that barely concentrate the sleeve still span "
               f"{spread_near:.2f} points of gap, against {full_spread:.2f} "
               f"across the whole set -- so what the scheme tilts towards "
               f"matters as much as how far it concentrates."))

    # The weighting touches `intl_eq` and nothing else, so any strategy with
    # no foreign exposure must come back identical under every scheme. That it
    # does is the cheapest available check that the panels differ only where
    # intended.
    spread_note = ""
    if change_cols:
        moved_mask = ranking[change_cols].abs().max(axis=1) >= 1e-9
        unchanged = ranking[~moved_mask]
        moved = ranking[moved_mask]
        parts = []
        if len(moved):
            widest = moved.assign(
                _span=moved[change_cols].max(axis=1)
                - moved[change_cols].min(axis=1)).sort_values("_span")
            parts.append(
                f"Among the strategies holding international equity, "
                f"{str(widest['label'].iloc[-1])} is the most "
                f"weighting-sensitive, spanning "
                f"{float(widest['_span'].iloc[-1]):.2f} percentage points "
                f"across the schemes, and "
                f"{str(widest['label'].iloc[0])} the least, at "
                f"{float(widest['_span'].iloc[0]):.2f}.")
        if len(unchanged):
            parts.append(
                f"The {len(unchanged)} strategies with no foreign exposure "
                f"({_and_list([str(v) for v in unchanged['label']])}) are "
                f"identical under every scheme to every decimal place, which "
                f"is the cheapest available check that the panels differ only "
                f"in the sleeve.")
        spread_note = " ".join(parts)

    figure_list = "\n".join(f"* `{f}`" for f in figures)
    intro = _header(
        "18 - How the International Sleeve Is Weighted",
        "Whether the headline needs an equal-weighted foreign leg, or "
        "survives sleeves an investor could actually have bought.")

    body = f"""
## 1. The construction under test

Every result in this project rests on an international equity leg built as a
**leave-one-out equal-weighted** average of the other {n_markets - 1} markets.
That is defensible and unusually favourable. An equal-weighted portfolio of
{n_markets} national markets is a more diversified object than any index a
person could have bought: it holds as much Portugal as it holds the United
States, it rebalances into whatever has fallen, and it never lets one market
dominate.

That matters here specifically, because the headline finding -- 100%
international beating the 50/50 domestic/international split that the
replicated paper lands on -- is a claim about how much diversification the
foreign sleeve delivers. If the equal weighting is doing that work, the
divergence is an artefact rather than a finding.

This section rebuilds the panel under {len(schemes)} weighting schemes and
re-runs the headline comparison through the same summariser, so the answers
differ in the weighting and in nothing else.

## 2. The schemes, and why these ones

JST supports very few honest cross-country weights. A series has to be in
comparable units across countries and complete enough not to change the
sleeve's membership from one year to the next; that rules out the nominal
`gdp`, `exports`, `tloans` and `wage` columns, which carry country-specific
currency units, and the ratio columns, which are gappy and are not sizes.
What survives is population, Maddison real GDP per head, their product, and
one scheme estimated from the returns themselves:

{spectrum_tbl}

Three properties hold for all of them:

* **Every weight is lagged.** Sizes are read from year `t-1` and the
  inverse-volatility estimate uses a strictly prior window, so no weight is
  formed from a number the investor could not yet have seen -- the same
  discipline `docs/15` applies to valuation terciles.
* **Every panel is paired.** All schemes share `years`, `countries` and
  `available`, so the bootstrap draws identical calendar history for each.
* **None of them is capitalisation weighting.** These are proxies. They
  reproduce the concentration that makes a real index a real index; they do
  not reproduce the wedge between an economy's size and its listed market's,
  and the PPP-based ones understate a market whose currency is temporarily
  strong -- Japan in the late 1980s most of all.

The set is deliberately two-dimensional. Real GDP and population concentrate
the sleeve heavily; GDP per capita and inverse volatility barely concentrate
it at all while tilting it somewhere quite different. That is what lets
Section 5 separate the effect of concentration from the effect of the tilt.

## 3. How much concentration each adds

{conc_tbl}

Equal weighting holds the effective number of markets at however many have
data that year -- {n_markets} in most years, {mean_equal_markets:.1f} on
average once the war-time gaps are counted -- which is the maximum any scheme
can reach.
{f"Averaged over the panel the most concentrated scheme is {str(tightest['label'])}, at an effective {float(tightest['effective_markets']):.1f} markets." if tightest is not None else ""}

## 4. The headline, under every weighting

At γ = {gamma:g} over {int(notes['n_paths']):,} lifetimes:

{ranking_tbl}

As a change against the equal-weighted panel:

{change_tbl}

{headline}

{spread_note}

## 5. Concentration, or the tilt?

{mech}

{moments_tbl}

## 6. What this changes

* {"The equal-weighted sleeve is the most favourable construction of those tested, and the levels in every table of this project reflect that." if equal_is_kindest else f"The equal weighting is **not** the construction most favourable to the finding. {str(kindest['label'])} produces a larger gap ({float(kindest['gap_pct']):+.2f}% against {ref_gap:+.2f}%), so the headline is not simply resting on the kindest sleeve available." if kindest is not None else ""}
  Either way a reader should treat the certainty equivalents as
  construction-dependent.
* {"The ordering that this project diverges from the replicated paper on does not survive every reweighting, so that divergence should be attributed to panel construction." if found["ordering_changes"] else "The ordering that this project diverges from the replicated paper on survives every reweighting tested, so the divergence is not manufactured by the equal weighting -- though the margin narrows."}
* None of these is capitalisation weighting. The honest reading is that this
  section brackets the answer rather than settling it: the truth sits between
  an equal-weighted sleeve nobody could buy and a PPP-GDP sleeve that
  misprices strong-currency markets.

## 7. Figures

{figure_list}

## 8. Reproduction

```bash
python main.py --steps 18
```

Runtime {float(notes['elapsed_seconds']):.0f}s at {int(notes['n_paths']):,} paths per
weighting, γ = {gamma:g}. Tables in `{cfg['run']['table_dir']}/sleeve_*.csv`.
"""
    return _write(path, [intro, body])


def write_doc_19(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """How much of the headline rests on any one country, or any one era."""
    infl = frames["influence"]
    period = frames["period"]
    chan = frames.get("channels", pd.DataFrame())
    profile = frames.get("profile", pd.DataFrame())
    why = notes.get("why", {})
    gamma = float(notes["gamma"])
    found = notes["verdict"]
    jack = notes["jackknife"]
    floor = notes["floor"]
    baseline = float(jack.get("baseline_gap_pct", float("nan")))
    noise = float(floor.get("range_pct", float("nan")))

    infl_tbl = md_table(_compact(
        infl, ["dropped", "gap_pct", "shift_pct", "challenger_cec",
               "incumbent_cec"],
        {"dropped": "Country removed", "gap_pct": "Lead (%)",
         "shift_pct": "Change in the lead (pp)",
         "challenger_cec": "CEC, all-international",
         "incumbent_cec": "CEC, 50/50"}), floatfmt="{:.4f}")

    period_tbl = md_table(_compact(
        period, ["window", "country_years", "gap_pct"],
        {"window": "Window", "country_years": "Country-years",
         "gap_pct": "Lead (%)"}), floatfmt="{:.3f}")

    # -- verdicts, classified ---------------------------------------------
    if found["survives_every_deletion"]:
        headline = (
            f"**No single country carries the result.** All-international "
            f"leads the 50/50 split in all {found['n_countries']} delete-one "
            f"panels. Removing {found['worst_country']} costs the most, "
            f"taking the lead from {baseline:.2f}% to "
            f"{found['worst_gap_pct']:.2f}%, and it still leads.")
    else:
        broken = int(found["n_deletions_that_break_it"])
        headline = (
            f"**The result does not survive every deletion.** In {broken} of "
            f"{found['n_countries']} delete-one panels the 50/50 split "
            f"overtakes all-international; the worst is "
            f"{found['worst_country']}, which takes the lead to "
            f"{found['worst_gap_pct']:.2f}%. On this evidence the headline "
            f"is a statement about a particular set of markets rather than a "
            f"general one.")

    material = found.get("material_countries", [])
    if np.isfinite(noise) and noise > 0:
        noise_note = (
            f"Re-seeding the bootstrap on the **unmodified** panel moves the "
            f"lead across a range of {noise:.3f} points, which is the floor "
            f"any of these shifts has to clear to mean anything. "
            + (f"{len(material)} of {found['n_countries']} countries clear it "
               f"({_and_list(material)}); the rest are indistinguishable from "
               f"re-drawing the paths."
               if material else
               "No country clears it, so the panel shows no individually "
               "influential market at all."))
    else:
        noise_note = ""

    t_stat = float(jack.get("t_stat", float("nan")))
    if found.get("excludes_zero") and jack.get("marginal"):
        interval = (
            f"The interval excludes zero, but only just: the implied "
            f"t-statistic is {t_stat:.2f} against a threshold of 1.96, and "
            f"the lower bound clears zero by "
            f"{float(jack.get('ci_low', float('nan'))):.2f} points. The "
            f"ordering is supported by the panel rather than only by the "
            f"simulation, and it is supported *thinly*. A reader should treat "
            f"the direction as established and the magnitude as barely "
            f"resolved.")
    elif found.get("excludes_zero"):
        interval = (
            f"The interval excludes zero comfortably — the implied "
            f"t-statistic is {t_stat:.2f} — so the ordering is supported by "
            f"the panel and not merely by the simulation.")
    else:
        interval = (
            f"**The interval includes zero.** With sixteen countries the "
            f"panel cannot distinguish this lead from no lead at all, whatever "
            f"the Monte Carlo precision suggests, and the headline should be "
            f"read as directional rather than established.")

    if found.get("all_windows_hold"):
        stability = (
            f"**The ordering holds in every window.** The weakest is "
            f"{found.get('weakest_window', '?')} at "
            f"{float(found.get('weakest_window_gap_pct', float('nan'))):.2f}%. "
            f"An investor standing in 1950 with only the record to that date "
            f"would have reached the same ranking as one standing today.")
    else:
        held = int(found.get("windows_holding", 0))
        stability = (
            f"**The ordering does not hold in every window**: it survives "
            f"{held} of {int(found.get('n_windows', 0))}. The weakest is "
            f"{found.get('weakest_window', '?')} at "
            f"{float(found.get('weakest_window_gap_pct', float('nan'))):.2f}%. "
            f"That makes the finding era-dependent, and the era it depends on "
            f"should be named whenever it is quoted.")

    channel_tbl = md_table(_compact(
        chan, ["dropped", "sleeve_channel_pct", "domestic_channel_pct",
               "implied_shift_pct", "measured_shift_pct"],
        {"dropped": "Country removed",
         "sleeve_channel_pct": "Sleeve channel S (%)",
         "domestic_channel_pct": "Domestic channel D (%)",
         "implied_shift_pct": "(S-D)/2", "measured_shift_pct": "Measured"}),
        floatfmt="{:.2f}") if len(chan) else "_not computed_"

    channel_note = ""
    if len(chan):
        agree = float(np.corrcoef(chan["implied_shift_pct"],
                                  chan["measured_shift_pct"])[0, 1])
        by_sleeve = chan[chan["channel"] == "sleeve"]
        channel_note = (
            f"The split reproduces the measured shifts almost exactly "
            f"(correlation {agree:.3f}), so it is a fair reading of them "
            f"rather than a story laid over the top. "
            f"{len(by_sleeve)} of {len(chan)} deletions work mainly through "
            f"the sleeve.")

    profile_tbl = md_table(_compact(
        _pct(profile.sort_values("sleeve_geometric_delta"),
             ["own_arithmetic", "own_geometric", "own_sd", "volatility_drag"]),
        ["iso", "own_arithmetic", "own_geometric", "volatility_drag",
         "own_sd", "sleeve_geometric_delta"],
        {"iso": "Market", "own_arithmetic": "Own arithmetic mean (%)",
         "own_geometric": "Own geometric mean (%)",
         "volatility_drag": "Volatility drag (pp)", "own_sd": "SD (%)",
         "sleeve_geometric_delta": "Effect on the sleeve's compound return (pp)"}),
        floatfmt="{:.2f}") if len(profile) else "_not computed_"

    why_note = ""
    if why:
        n_mkt = int(why.get("n_markets", 0))
        pole = str(why.get("sleeve_pole", "?"))
        home = str(why.get("home_pole", "?"))
        corr_geo = float(why.get("corr_sleeve_geometric_delta", float("nan")))
        corr_arith = float(why.get("corr_own_arithmetic", float("nan")))
        corr_drag = float(why.get("corr_volatility_drag", float("nan")))
        pole_drag = (
            "the largest volatility drag in the panel"
            if int(why.get("sleeve_pole_drag_rank", 0)) == 1 else
            f"the {_ordinal(int(why.get('sleeve_pole_drag_rank', 0)))}-largest "
            f"volatility drag of {n_mkt}")
        parts = [
            f"A deletion's effect on the headline tracks what it does to the "
            f"**sleeve's compound return** (correlation {corr_geo:+.2f}), not "
            f"the removed market's own average return (correlation "
            f"{corr_arith:+.2f}). So the load-bearing market is not the one "
            f"with the best domestic history -- it is the one the fifteen-way "
            f"average could least afford to lose.",
            f"**{pole}** is that market, and the reason is the gap between "
            f"its two means: an arithmetic mean of "
            f"{float(why.get('sleeve_pole_arithmetic', float('nan'))):.2%} "
            f"against a geometric mean of "
            f"{float(why.get('sleeve_pole_geometric', float('nan'))):.2%}, "
            f"{pole_drag}. An equal-weighted average of fifteen markets adds "
            f"up *arithmetic* returns each year and diversifies the "
            f"volatility away, so the sleeve collects {pole}'s high mean "
            f"without paying its drag, while its own residents pay the drag "
            f"in full. It is an excellent constituent of somebody else's "
            f"sleeve and a mediocre thing to hold alone, so removing it hits "
            f"the all-sleeve strategy hardest and narrows the lead."]
        if why.get("usa_present"):
            widen = "widens" if why.get("usa_widens") else "narrows"
            drag_note = ("one of the smallest drags in the panel"
                         if why.get("usa_drag_is_small") else
                         f"the {_ordinal(int(why.get('usa_drag_rank', 0)))}"
                         f"-largest drag of {n_mkt}")
            parts.append(
                f"**The United States is the mirror image**, which answers "
                f"the question most readers arrive with. It is the "
                f"{_ordinal(int(why.get('usa_arithmetic_rank', 0)))}-best "
                f"market by arithmetic mean "
                f"({float(why.get('usa_arithmetic', float('nan'))):.2%}) and "
                f"the {_ordinal(int(why.get('usa_geometric_rank', 0)))}-best "
                f"by geometric mean "
                f"({float(why.get('usa_geometric', float('nan'))):.2%}) -- "
                f"{drag_note}. Almost all of its return survives being held "
                f"on its own, so its value is concentrated in the role the "
                f"50/50 split holds and the all-international strategy does "
                f"not. Removing it costs the sleeve only "
                f"{float(why.get('usa_delta', float('nan'))):.2f} points of "
                f"compound return but takes a good home market out of the "
                f"pool, so it hurts the 50/50 split more and {widen} the "
                f"lead by {abs(float(why.get('usa_shift', float('nan')))):.2f} "
                f"points. The United States is not what the result rests on; "
                f"it is what the *comparison* rests on.")
        if home != pole:
            home_drag = ("a small volatility drag"
                         if why.get("home_pole_drag_is_small") else
                         "a large volatility drag of its own"
                         if why.get("home_pole_drag_is_large") else
                         "a middling volatility drag")
            parts.append(
                f"The largest domestic channel of all belongs to **{home}** "
                f"({float(why.get('home_pole_domestic_channel', float('nan'))):.2f}% "
                f"against a sleeve channel of "
                f"{float(why.get('home_pole_sleeve_channel', float('nan'))):.2f}%), "
                f"and it has {home_drag} -- so the arithmetic-versus-geometric "
                f"reading is not the whole of the domestic side either.")
        parts.append(
            f"The explanation should not be pushed further than the column it "
            f"rests on. Across the panel the correlation between a deletion's "
            f"effect and the removed market's volatility drag is only "
            f"{corr_drag:+.2f}: the drag explains why {pole} in particular is "
            f"worth more to others than to itself, not the pattern as a "
            f"whole.")
        counter = str(why.get("counterexample", ""))
        if counter:
            parts.append(
                f"{counter} makes the point. It has a higher arithmetic mean "
                f"still "
                f"({float(why.get('counterexample_arithmetic', float('nan'))):.2%}) "
                f"and removing it costs the sleeve only "
                f"{float(why.get('counterexample_delta', float('nan'))):.2f} "
                f"points, so a high average alone does not make a market "
                f"load-bearing. How its good years line up against the other "
                f"fourteen matters too, and that is measured in the last "
                f"column above rather than argued from the first.")
        why_note = "\n\n".join(parts)

    figure_list = "\n".join(f"* `{f}`" for f in figures)
    intro = _header(
        "19 - How Much Rests on One Country, or One Era",
        "Delete-one-country influence, the standard error sixteen countries "
        "actually support, and whether the ranking is stable through time.")

    body = f"""
## 1. The question the panel raises

`docs/05` varies the preferences and the lifecycle. `docs/18` varies how the
international sleeve is weighted. Neither touches what a sceptical reader asks
about first: the panel is **sixteen developed markets that survived**, and a
result assembled from sixteen histories could be one history wearing a
disguise. If dropping the United States overturns the ranking, this project is
about the United States.

Three questions, on the same machinery and scored by the same summariser that
produces the headline table itself:

* **Influence.** Rebuild the panel once per country with that country removed,
  and re-run.
* **Uncertainty.** Those runs form a delete-one jackknife, which gives a
  standard error reflecting the *panel's* size rather than the Monte Carlo's.
* **Stability.** Re-run on expanding windows of history, and on the two halves.

The deletion is genuine. A dropped market disappears from every other
country's international sleeve as well as from the set its own domestic leg is
drawn from, so each run answers "what would this project say if that market's
history had never been recorded" rather than the much weaker "what if we had
chosen not to invest there".

## 2. The noise floor

Every delete-one run draws its own bootstrap paths, so it will differ from the
full panel even when the country it dropped carried no information at all.
Before reading any shift as a finding, the study re-runs the **unmodified**
panel under {int(floor.get('seeds', 0))} seeds.

{noise_note}

## 3. Removing one country at a time

At γ = {gamma:g} over {int(notes['n_paths']):,} lifetimes per run, with the
full-panel lead at {baseline:.2f}%:

{infl_tbl}

{headline}

## 3.1 Why that country, and not the obvious one

The natural guess is that the load-bearing market is the one with the best
domestic returns, and that removing it makes the domestic half of the 50/50
split look worse. The data says otherwise, and the reason is worth setting out
because it is a general point about what an averaged sleeve does.

Every country sits in the panel twice over: once as somebody's home market,
and once inside the fifteen-market average that everybody *else* holds as
their international leg. The two strategies weight those roles differently --
all-international is entirely sleeve, the 50/50 split is half sleeve and half
domestic -- so writing `S` for the effect of a deletion on the first and `D`
for the implied effect on the domestic half:

    change in all-international  =  S
    change in the 50/50 split    =  (S + D) / 2
    change in the gap            =  (S - D) / 2

A market whose value lies mostly in other people's sleeves has a large
negative `S`, and removing it narrows the gap. One whose value lies mostly in
being its own home market has a large negative `D`, and removing it widens the
gap.

{channel_tbl}

{channel_note}

### What separates the two

{profile_tbl}

{why_note}

## 4. What sixteen countries actually support

The delete-one runs give a jackknife standard error of
**{float(jack.get('standard_error', float('nan'))):.2f} points** on a lead of
{baseline:.2f}%, for a 95% interval of
[{float(jack.get('ci_low', float('nan'))):.2f},
{float(jack.get('ci_high', float('nan'))):.2f}].

{interval}

This is the number to quote, and it is much wider than the Monte Carlo error.
A hundred thousand bootstrap paths make the simulation error negligible
without adding a single country of evidence; the panel's own sampling error is
untouched by how long the computer runs.

## 5. Is the ranking stable through time?

{period_tbl}

{stability}

## 6. What this changes

* {"No single market carries the headline, so it is not a restatement of one country's history." if found["survives_every_deletion"] else "At least one deletion overturns the headline, so it should be stated as a property of this particular set of markets."}
* The honest precision on the headline gap is the jackknife interval in
  Section 4, not the Monte Carlo one. Every certainty equivalent in this
  project is quoted to four decimal places because that is what the
  simulation resolves; the *panel* resolves far less{" -- and at a t-statistic of " + f"{t_stat:.2f}" + " this particular result sits close enough to the threshold that it should be quoted with its interval, never alone" if jack.get("marginal") else ""}.
* {"The ranking is stable across every window of history tested, which is the strongest of the three checks here: it is the one an investor could have acted on contemporaneously." if found.get("all_windows_hold") else "The ranking is not stable across every window, so it should be quoted with the era it depends on."}

## 7. Figures

{figure_list}

## 8. Reproduction

```bash
python main.py --steps 19
```

Runtime {float(notes['elapsed_seconds']):.0f}s at {int(notes['n_paths']):,} paths per
run, γ = {gamma:g}. Tables in `{cfg['run']['table_dir']}/panel_*.csv`.
"""
    return _write(path, [intro, body])


def write_doc_20(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """What costs do to the headline, and how small a cost undoes it."""
    common = frames["common"]
    differential = frames["differential"]
    anchors = frames["anchors"]
    ranking = frames["ranking"]
    gamma = float(notes["gamma"])
    found = notes["verdict"]
    base = float(found["baseline_gap_pct"])
    be_bp = float(found["break_even_differential_bp"])
    be_common_bp = float(found["break_even_common_bp"])

    common_tbl = md_table(_compact(
        common.assign(bp=common["fee"] * 1e4),
        ["bp", "gap_pct"],
        {"bp": "Fee on every asset (bp)", "gap_pct": "Lead (%)"}),
        floatfmt="{:.2f}")
    diff_tbl = md_table(_compact(
        differential.assign(bp=differential["differential"] * 1e4),
        ["bp", "gap_pct"],
        {"bp": "Extra fee on the foreign leg (bp)", "gap_pct": "Lead (%)"}),
        floatfmt="{:.2f}")
    anchor_tbl = md_table(_compact(
        anchors, ["label", "basis_points", "gap_pct"],
        {"label": "Reference", "basis_points": "Differential (bp)",
         "gap_pct": "Lead at that differential (%)"}), floatfmt="{:.2f}")
    rank_col = [c for c in ranking.columns if c.startswith("cec_crra_")][0]
    rank_tbl = md_table(_compact(
        ranking, ["label", rank_col, "prob_ruin"],
        {"label": "Strategy", rank_col: "CEC", "prob_ruin": "P(ruin)"}),
        floatfmt="{:.4f}")

    common_erosion = (float(common["gap_pct"].iloc[0])
                      - float(common["gap_pct"].iloc[-1]))
    common_top_bp = float(common["fee"].iloc[-1]) * 1e4
    common_note = (
        f"A fee charged on all four sleeves alike never closes the gap on "
        f"this grid, which is the control working: a cost common to every "
        f"strategy largely cancels out of a comparison between them. It does "
        f"not cancel entirely -- {common_top_bp:.0f} bp on everything still "
        f"costs {common_erosion:.2f} points of lead, because the two "
        f"strategies accumulate different amounts of wealth for the fee to be "
        f"charged on -- but the effect is a fraction of what the same fee "
        f"does when it falls on the foreign leg alone."
        if found["common_is_near_neutral"] else
        f"A fee charged on all four sleeves alike closes the gap at "
        f"{be_common_bp:.0f} bp. That is not what a common cost is supposed "
        f"to do, and it means the strategies differ enough in their asset "
        f"mix for even an even-handed fee to fall on them unequally.")

    if not found["differential_closes_the_gap"]:
        headline = (
            f"**No differential on this grid undoes the result.** The lead "
            f"starts at {base:.2f}% and is still positive at the top of the "
            f"grid, so the international advantage is not fragile to fund "
            f"costs at any level tested.")
    elif found["below_cheapest_anchor"]:
        headline = (
            f"**The result does not survive realistic fund costs.** The lead "
            f"of {base:.2f}% is cancelled by a differential of "
            f"{be_bp:.0f} basis points -- less than the gap between a "
            f"modern domestic and international index fund. On this evidence "
            f"the divergence from the replicated study is inside the noise of "
            f"what an investor pays to implement it.")
    elif found["inside_historic_range"]:
        headline = (
            f"**The result survives modern fund costs and not historic "
            f"ones.** The lead of {base:.2f}% is cancelled by a differential "
            f"of {be_bp:.0f} basis points. That is wider than the gap "
            f"between today's domestic and international index funds and "
            f"narrower than what the same funds charged two decades ago, so "
            f"whether the advantage is real for a given investor depends on "
            f"what they can actually buy.")
    else:
        headline = (
            f"**The result survives every fund cost a real investor has "
            f"faced.** The lead of {base:.2f}% needs a differential of "
            f"{be_bp:.0f} basis points to cancel it, wider than any "
            f"reference expense ratio below.")

    figure_list = "\n".join(f"* `{f}`" for f in figures)
    intro = _header(
        "20 - Fees, and the Differential That Undoes the Headline",
        "Every return in this project is gross. Nobody earns a gross return, "
        "and the strategies at stake hold different amounts of the expensive "
        "sleeve.")

    body = f"""
## 1. Why a fee is not neutral here

A cost common to every strategy mostly cancels out of a comparison between
them, which is the usual justification for working in gross returns. That
justification does not extend to this project's one divergence from the study
it re-implements, because the two strategies at stake hold different amounts
of the sleeve that costs more.

All-international pays the international fund's expense ratio on the whole
portfolio. The 50/50 split pays it on half. A **differential** between
domestic and international funds therefore falls on them unequally, and it
compounds over a sixty-eight-year lifetime.

An expense ratio is levied on assets rather than on returns, so a gross real
return `r` net of a fee `f` is `(1 + r)(1 - f) - 1` rather than `r - f`. The
difference is second-order in one year and not in sixty-eight. Fees are
applied to the panel before the bootstrap sees it, and `available` is left
alone, so every fee level draws exactly the same blocks.

## 2. The control: a fee on everything

{common_tbl}

{common_note}

## 3. The question: a fee on the foreign leg alone

At γ = {gamma:g} over {int(notes['n_paths']):,} lifetimes per level:

{diff_tbl}

{headline}

## 4. Against what an investor actually pays

{anchor_tbl}

These expense ratios are **configured anchors, not findings**. Nothing in this
project's data can verify them; they are here to put the swept grid on a scale
a reader recognises. {"They bracket the break-even, which is the useful thing: it sits inside the range of costs this comparison has actually been implementable at." if found["inside_historic_range"] and not found["below_cheapest_anchor"] else "" }

{f"The cheapest reference that closes the gap on its own is **{found['cheapest_anchor_that_closes_it']}**." if found["cheapest_anchor_that_closes_it"] else "No reference expense ratio on this list closes the gap on its own."}

## 5. The full ranking, before any fee

{rank_tbl}

## 6. What this changes

* The headline gap and a plausible fee differential are quantities of the
  **same order**. That is the practical finding here, and it is not visible
  anywhere in the gross-return tables that make up the rest of this project.
* {"A reader implementing this at modern index-fund costs keeps most of the advantage; one paying an active international fund's fee does not." if found["inside_historic_range"] else "The advantage survives every reference cost tested, so implementation cost is not what decides this."}
* What is **not** modelled: trading costs, spreads, taxes, platform fees, and
  the fact that index funds did not exist for most of this sample. Before
  roughly 1975 a diversified foreign portfolio was expensive and often
  impossible to hold at all, so the fee grid is a sensitivity rather than a
  history of what was available.

## 7. Figures

{figure_list}

## 8. Reproduction

```bash
python main.py --steps 20
```

Runtime {float(notes['elapsed_seconds']):.0f}s at {int(notes['n_paths']):,} paths per
level, γ = {gamma:g}. Tables in `{cfg['run']['table_dir']}/fee_*.csv`.
"""
    return _write(path, [intro, body])


# ---------------------------------------------------------------------------
# Step 21 - the realised record
# ---------------------------------------------------------------------------
def write_doc_21(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """The lifetimes the panel actually contains, run without resampling."""
    census = frames["census"]
    summary = frames["summary"]
    by_country = frames["by_country"]
    gamma = float(notes["gamma"])
    found = notes["verdict"]
    effective = notes["effective"]
    interval = notes["interval"]
    signs = notes["signs"]
    spread = notes["dispersion"]
    challenger, incumbent = notes["pair"]

    cec_col = [c for c in summary.columns if c.startswith("cec_crra_")][0]
    summary_tbl = md_table(_compact(
        summary, ["label", cec_col, "median_retirement_consumption",
                  "p5_retirement_consumption", "prob_ruin"],
        {"label": "Strategy", cec_col: "CEC",
         "median_retirement_consumption": "Median retirement consumption",
         "p5_retirement_consumption": "5th percentile", "prob_ruin": "P(ruin)"}),
        floatfmt="{:.4f}")
    census_tbl = md_table(_compact(
        census, ["iso", "usable_years", "longest_unbroken", "cohorts",
                 "first_start", "last_start"],
        {"iso": "Market", "usable_years": "Usable years",
         "longest_unbroken": "Longest unbroken run", "cohorts": "Lifetimes",
         "first_start": "Earliest birth year", "last_start": "Latest"}),
        floatfmt="{:.0f}")
    country_tbl = md_table(_compact(
        by_country, ["iso", "cohorts", "mean_gap_pct", "median_gap_pct",
                     "win_rate"],
        {"iso": "Market", "cohorts": "Lifetimes",
         "mean_gap_pct": "Mean lead (%)", "median_gap_pct": "Median (%)",
         "win_rate": "Share of lifetimes ahead"}), floatfmt="{:.2f}")

    starved = census[census["cohorts"] < 12]
    starved_names = ", ".join(
        f"{r['iso']} ({int(r['cohorts'])}, from {int(r['first_start'])})"
        for _, r in starved.iterrows())

    if found["winner_is_expected"]:
        headline = (
            f"**The ordering survives with no resampling at all.** Over the "
            f"{found['n_cohorts']} complete lifetimes the panel can support, "
            f"all-international delivers a certainty equivalent "
            f"{found['cec_gap_pct']:.1f}% above the 50/50 split, and it is "
            f"ahead in {found['cohort_win_rate']:.0%} of them. Whatever else "
            f"the headline is, it is not an artefact of the block bootstrap.")
    else:
        headline = (
            f"**The ordering does not survive without resampling.** Over the "
            f"{found['n_cohorts']} realised lifetimes the best strategy is "
            f"`{found['winner']}`, not `{challenger}`. That is a direct "
            f"contradiction of the bootstrap result and the rest of this "
            f"paper has to be read against it.")

    if found["interval_excludes_zero"]:
        interval_note = (
            f"Resampling *countries* rather than cohorts gives a mean lead of "
            f"{found['mean_cohort_gap_pct']:.1f}% with a 95% interval of "
            f"[{found['ci_low']:.1f}, {found['ci_high']:.1f}], which excludes "
            f"zero.")
    else:
        interval_note = (
            f"Resampling *countries* rather than cohorts gives a mean lead of "
            f"{found['mean_cohort_gap_pct']:.1f}% with a 95% interval of "
            f"[{found['ci_low']:.1f}, {found['ci_high']:.1f}] -- an interval "
            f"that contains zero. The direction is what the realised record "
            f"supports; the magnitude is not resolved by it.")

    unanimous = (
        "Every market in the panel favours it."
        if found["every_country_favours_first"] else
        f"{found['countries_won']} of {found['countries_total']} markets "
        f"favour it; the exceptions are named below and they are the "
        f"interesting rows.")

    figure_list = "\n".join(f"* `{f}`" for f in figures)
    intro = _header(
        "21 - The Realised Record, Without the Bootstrap",
        "One country, one birth year, sixty-eight years of history in the "
        "order they happened. Nothing is drawn.")

    body = f"""
## 1. What a cohort is

Every other number in this project comes from resampled histories. That is
the right way to get a distribution out of 131 years, and it leaves one
question open that no amount of resampling can answer: is the result a
property of the world, or of the sampler?

A **cohort** here is one country and one birth year. The investor turns 25 in
the first year of the window, holds the strategy through that country's
realised returns and the realised leave-one-out sleeve of every other market,
in calendar order, and dies {int(cfg['lifecycle']['age_death'])} years later.
There is exactly one such lifetime per (country, birth year) the panel can
support, and none of it is drawn.

Labour income is **deterministic** in this section. Elsewhere it carries
permanent and transitory shocks; with a few hundred realised histories those
shocks would be a large share of the cross-sectional spread and none of it
would be about returns.

## 2. How thin the record really is

{census_tbl}

The panel supports **{effective['n_cohorts']} complete lifetimes**. It does
not contain {effective['n_cohorts']} pieces of evidence. Adjacent cohorts in
the same country share {int(effective['horizon']) - 1} of their
{int(effective['horizon'])} years, and cut into non-overlapping lifetimes the
same record yields **{effective['n_independent']}** -- an overlap ratio of
{effective['overlap_ratio']:.0f} to one. Every cohort also lives through the
same two world wars, so even those are not independent of each other.

**A market closure removes a lifetime, not a year.** The bootstrap refuses
blocks that span a gap and keeps drawing; a cohort that spans one cannot be
run at all. {starved_names}. Every runnable German, Japanese and Spanish
lifetime therefore *begins after* that country's catastrophe and rides the
recovery. This design is structurally kinder to domestic equity than the
bootstrap is, and the direction of that bias should be held in mind for the
rest of the section.

## 3. What the realised lifetimes paid

At γ = {gamma:g}, over {found['n_cohorts']} realised lifetimes:

{summary_tbl}

{headline}

{interval_note} Counting by market rather than by cohort -- which gives the
United States one vote instead of sixty-four -- the lead holds in
{signs['countries_won']} of {signs['countries_total']}. {unanimous}

## 4. Market by market

{country_tbl}

## 5. Why the realised lead is larger than the resampled one

The bootstrap headline and the number above are not the same quantity and
should not be read as an estimate and a re-estimate of one thing. A
bootstrapped lifetime is a mosaic of blocks drawn from different decades, so
a market that underperformed for forty years running contributes a few of
those blocks and the rest of the lifetime is spliced in from better eras. A
cohort cannot splice.

The realised record makes the consequence visible. Over the
{int(effective['horizon'])}-year windows the panel supports, a home market's
annualised real return ranges from {spread['worst_domestic_pp']:.1f}% to
{spread['best_domestic_pp']:.1f}% -- a spread of
{spread['domestic_sd_pp']:.2f} points of standard deviation. The
international sleeve over the identical years ranges from
{spread['worst_sleeve_pp']:.1f}% to {spread['best_sleeve_pp']:.1f}%, with a
standard deviation of {spread['sleeve_sd_pp']:.2f}.

That is the whole argument stated without a single resampled path: **there is
no realised sixty-eight-year window in which the diversified sleeve did
badly, and there are several in which a single home market was destroyed.**
The sleeve was ahead in {spread['share_sleeve_ahead']:.0%} of realised
lifetimes, by {spread['mean_excess_pp']:.2f} points a year on average.

## 6. What this changes

* The ordering is **not** an artefact of the block bootstrap. It is in the
  realised record, without resampling, in
  {signs['countries_won']} of {signs['countries_total']} markets.
* The honest interval on the realised lead is
  [{found['ci_low']:.1f}, {found['ci_high']:.1f}] from
  {effective['n_independent']} independent lifetimes. This section adds
  confidence in the *direction* and almost none in the magnitude.
* The design cannot see the worst domestic histories in the panel, because a
  lifetime cannot step over a market closure. The bootstrap can, which is one
  of the reasons to keep it as the headline.
* The extremes are worth naming: the best realised cohort for the sleeve was
  {found['best_cohort']} at {found['best_gap_pct']:.0f}%, the worst was
  {found['worst_cohort']} at {found['worst_gap_pct']:.0f}%.

## 7. Figures

{figure_list}

## 8. Reproduction

```bash
python main.py --steps 21
```

Runtime {float(notes['elapsed_seconds']):.0f}s over {found['n_cohorts']}
realised lifetimes, γ = {gamma:g}, {interval['n_boot']:,} cluster-bootstrap
draws over {interval['n_clusters']} markets. Tables in
`{cfg['run']['table_dir']}/cohort_*.csv`.
"""
    return _write(path, [intro, body])


# ---------------------------------------------------------------------------
# Step 22 - out of sample
# ---------------------------------------------------------------------------
def write_doc_22(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """Whether a solved schedule beats a constant mix on data it never saw."""
    transfer = frames["transfer"]
    benchmarks = frames["benchmarks"]
    gamma = float(notes["gamma"])
    found = notes["verdict"]
    stability = notes["stability"]
    cut = int(notes["cut_year"])

    transfer_tbl = md_table(_compact(
        transfer, ["label", "train_window", "test_window",
                   "in_sample_gain_pct", "transfer_gain_pct",
                   "ceiling_gain_pct"],
        {"label": "Family", "train_window": "Solved on",
         "test_window": "Scored on", "in_sample_gain_pct": "Gain where solved (%)",
         "transfer_gain_pct": "Gain where scored (%)",
         "ceiling_gain_pct": "Ceiling (%)"}), floatfmt="{:.2f}")
    bench_tbl = md_table(_compact(
        benchmarks, ["window", "label", "cec", "rank"],
        {"window": "Window", "label": "Strategy", "cec": "CEC",
         "rank": "Rank"}), floatfmt="{:.4f}")

    if found["no_run_transfers"]:
        headline = (
            f"**No solved schedule beats a constant mix out of sample.** In "
            f"all {found['runs']} runs the schedule solved on one half is "
            f"worse on the other half than simply holding the best fixed "
            f"strategy. The in-sample gains those sections report -- averaging "
            f"{found['mean_in_sample_gain_pct']:.2f}% -- are descriptions of "
            f"the window the search was given.")
    elif found["every_run_transfers"]:
        headline = (
            f"**Every solved schedule survives the split.** All "
            f"{found['runs']} runs beat the best fixed strategy on data they "
            f"were not fitted to, keeping a median "
            f"{found['median_retained_share']:.0%} of the in-sample gain.")
    elif found.get("asymmetric"):
        headline = (
            f"**The solved schedules transfer in "
            f"{found['runs_that_beat_the_benchmark']} of {found['runs']} "
            f"runs, and which ones is the finding.** A schedule learned on "
            f"{found['earlier_window']} and applied to "
            f"{found['later_window']} keeps "
            f"{found['forward_gain_pct']:+.2f}%; run backwards it delivers "
            f"{found['backward_gain_pct']:+.2f}%. The earlier half holds two "
            f"world wars, several market closures and the Depression; the "
            f"later half holds the post-war expansion. A schedule fitted to "
            f"the turbulent window carries something forward into the calm "
            f"one; a schedule fitted to the calm window learns a world that "
            f"never came back. An investor solving today is in the second "
            f"position.")
    else:
        headline = (
            f"**The solved schedules transfer in "
            f"{found['runs_that_beat_the_benchmark']} of {found['runs']} "
            f"runs.** Averaged over both directions the in-sample gain is "
            f"{found['mean_in_sample_gain_pct']:.2f}% and what survives the "
            f"split is {found['mean_transfer_gain_pct']:.2f}%. A search with "
            f"sixty-eight free parameters and "
            f"{int(notes['independent_lifetimes'])} independent lifetimes of "
            f"data was always going to fit some noise; this measures how "
            f"much.")

    stable_note = (
        "The fixed strategies keep exactly their order across the two halves, "
        "so the split is not simply comparing two different worlds."
        if stability.get("stable") else
        f"The fixed strategies do **not** keep their order across the halves "
        f"-- {int(stability.get('n_positions_moved', 0))} positions move, "
        f"though the winner is "
        f"{'the same' if stability.get('same_winner') else 'different'}. Some "
        f"of what fails to transfer below is the world changing between the "
        f"halves rather than the search overfitting, and this test cannot "
        f"separate the two.")

    figure_list = "\n".join(f"* `{f}`" for f in figures)
    intro = _header(
        "22 - Do the Solved Schedules Survive Data They Did Not See?",
        "Three sections of this paper hand a search sixty-eight free "
        "parameters and report what it found on the data it was given.")

    body = f"""
## 1. What is being tested, and why it needs testing

Sections on the glide path and the whole-simplex allocation solve a schedule
by coordinate ascent and report its gain over the fixed benchmarks. Both
gains are measured on the same history the search was run over. That is the
standard way to overstate a result: with sixty-eight free parameters and
about {int(notes['independent_lifetimes'])} independent lifetimes in
the panel -- the count section #cohorts arrives at -- a search can fit a good
deal of noise, and an in-sample gain is an upper bound on what an investor
standing at the start could have had.

The design here splits the calendar record at {cut}, solves on one half and
scores on the other, against three references:

* **Gain where solved** -- the number those sections report today.
* **Gain where scored** -- the schedule solved on the training half,
  evaluated on the other half, against the best fixed strategy there. This is
  what an investor of the period could actually have held.
* **Ceiling** -- the same family solved on the test half itself, which is
  what the search finds when it already knows the answer.

Both directions are run, because the two halves of this panel are not
interchangeable: the first contains two world wars and the second contains
the post-war expansion.

## 2. What transferred

At γ = {gamma:g} over {int(notes['n_paths']):,} lifetimes per window:

{transfer_tbl}

{headline}

The benchmark that the solved schedules are measured against is
`{transfer['benchmark'].iloc[0]}` in every run, which is worth stating
plainly: the strategy that does transfer is a **constant mix**, held
unchanged for sixty-eight years.

## 3. Are the two halves the same world?

{bench_tbl}

{stable_note}

## 4. What this changes

* The gains reported for solved schedules elsewhere in this paper should be
  read as **upper bounds**. The transferable part is
  {found['mean_transfer_gain_pct']:.2f}% on average, against
  {found['mean_in_sample_gain_pct']:.2f}% in sample.
* {"Solving beats not solving, out of sample, in the majority of runs." if found['runs_that_beat_the_benchmark'] > found['runs'] / 2 else "Solving does not reliably beat not solving. The practical reading is that the schedule sections are worth keeping as descriptions of what the optimiser wants, and not as advice."}
* The headline of this paper does not depend on any of it. The comparison
  that carries the paper is between fixed strategies, none of which is
  fitted to anything.
* **What this test cannot do**: prove that a failure to transfer is
  overfitting rather than a changed world. The two halves are not draws from
  one process, and the benchmark table above is the evidence for that.

## 5. Figures

{figure_list}

## 6. Reproduction

```bash
python main.py --steps 22
```

Runtime {float(notes['elapsed_seconds']):.0f}s at {int(notes['n_paths']):,}
paths per window, γ = {gamma:g}, split at {cut}. Tables in
`{cfg['run']['table_dir']}/oos_*.csv`.
"""
    return _write(path, [intro, body])


# ---------------------------------------------------------------------------
# Step 23 - human capital
# ---------------------------------------------------------------------------
def write_doc_23(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """What correlated human capital does to the case for the home market."""
    curve = frames["curve"]
    ranking = frames["ranking"]
    gamma = float(notes["gamma"])
    found = notes["verdict"]
    fitted = notes["fitted"]

    curve_tbl = md_table(_compact(
        curve, ["correlation", "gap_pct", "winner"],
        {"correlation": "Correlation with the home market",
         "gap_pct": "All-international over 50/50 (%)", "winner": "Best"}),
        floatfmt="{:.2f}")
    level_cols = [c for c in ranking.columns if isinstance(c, float)]
    rank_tbl = md_table(
        ranking[["label"] + level_cols].rename(
            columns={"label": "Strategy",
                     **{c: f"rho = {c:g}" for c in level_cols}}),
        floatfmt="{:.4f}")

    if found["winner_ever_changes"]:
        headline = (
            f"**The ranking depends on the assumption.** The best strategy "
            f"changes across the swept correlations "
            f"({', '.join(found['winners_seen'])}), which means the headline "
            f"was resting on human capital being independent of the home "
            f"market rather than merely being flattered by it.")
    elif found["widens_with_correlation"]:
        headline = (
            f"**Correlated human capital widens the lead, and the ranking "
            f"never moves.** Going from independence to a correlation of "
            f"{found['highest_correlation']:.1f} moves the lead from "
            f"{found['baseline_gap_pct']:.2f}% to "
            f"{found['gap_at_highest_pct']:.2f}% -- "
            f"{found['change_pp']:+.2f} points, or about "
            f"{found['slope_per_10pp']:+.2f} points per 0.1 of correlation. "
            f"The direction is the one theory predicts, and the headline was "
            f"being conservative by assuming it away.")
    else:
        headline = (
            f"**Correlated human capital narrows the lead**, from "
            f"{found['baseline_gap_pct']:.2f}% at independence to "
            f"{found['gap_at_highest_pct']:.2f}% at a correlation of "
            f"{found['highest_correlation']:.1f}. That is the opposite of "
            f"what the textbook argument predicts and is worth explaining "
            f"rather than reporting.")

    figure_list = "\n".join(f"* `{f}`" for f in figures)
    intro = _header(
        "23 - When the Pay Cheque Is a Claim on the Home Market",
        "The textbook reason to hold less of your own market is that your "
        "salary is already invested in it. Every result so far assumes it "
        "is not.")

    body = f"""
## 1. The assumption being relaxed

Labour income in this model is a hump-shaped real profile multiplied by a
permanent random walk and a transitory shock, and those shocks have been
drawn independently of the return panel. That independence is a gift to
domestic equity. A worker whose employer, industry and tax base are the index
is long that index twice: once in the portfolio and once in the pay cheque.
Holding less of the home market than its weight in a global index is the
standard prescription that follows, and the model has been assuming the
premise away.

**The parameter is a correlation, not a loading.** The permanent innovation
becomes `rho * u + sqrt(1 - rho^2) * z`, with `u` the standardised domestic
equity return of the same year. That rotation preserves unit variance, so
raising `rho` changes *which part* of a career's risk is systematic without
changing how much risk a career carries. Any movement in the table below is
therefore the correlation and not extra income volatility smuggled in
alongside it. At `rho = 0` the arithmetic is untouched and every other result
in this project is unchanged to the last bit.

## 2. The sweep

At γ = {gamma:g} over {int(notes['n_paths']):,} lifetimes per level:

{curve_tbl}

{headline}

## 3. Every strategy, at every correlation

{rank_tbl}

{"The order is identical at every correlation tested." if not found["winner_ever_changes"] else "The order is not identical across the grid; the winner column above says where it moves."}
{"Domestic equity does not improve its rank anywhere on the grid, which is the direct check: if correlated human capital were going to rescue the home market, this is where it would show." if not found["domestic_ever_improves_rank"] else "Domestic equity improves its rank as the correlation rises, which is the mechanism working in the direction theory predicts -- though not far enough to change the winner."}

## 4. What this changes

* The direction is the one theory predicts, so the independence assumption
  used everywhere else in this paper is **conservative**: relaxing it makes
  the case for the home market worse, not better.
* The size is the useful part. Over a correlation range that runs past
  anything a labour economist would defend, the lead moves
  {found['change_pp']:+.2f} points. Against the fee differential of section
  #fees and the country-deletion range of section #panel, that is a
  second-order lever.
* **What is not modelled**: unemployment spells, industry, and any
  correlation between labour income and the *international* sleeve, which is
  not zero either and would push the other way. This is a bound on one
  channel, not a calibrated model of human capital.

## 5. Figures

{figure_list}

## 6. Reproduction

```bash
python main.py --steps 23
```

Runtime {float(notes['elapsed_seconds']):.0f}s at {int(notes['n_paths']):,}
paths per level, γ = {gamma:g}. Fitted slope
{fitted['slope_per_10pp']:+.3f} points per 0.1 of correlation
(R² = {fitted['r_squared']:.2f}). Tables in
`{cfg['run']['table_dir']}/human_capital_*.csv`.
"""
    return _write(path, [intro, body])


# ---------------------------------------------------------------------------
# Step 24 - mortality
# ---------------------------------------------------------------------------
def write_doc_24(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """A random lifespan instead of a fixed one, and what it changes."""
    curve = frames["curve"]
    ranking = frames["ranking"]
    gamma = float(notes["gamma"])
    found = notes["verdict"]

    curve_cols = [c for c in curve.columns if c.startswith("ruin_")]
    curve_tbl = md_table(_compact(
        curve, ["mortality", "life_expectancy", "gap_pct"] + curve_cols,
        {"mortality": "Mortality", "life_expectancy": "E[age at death]",
         "gap_pct": "All-international over 50/50 (%)",
         **{c: f"P(outlives the money): {c[5:]}" for c in curve_cols}}),
        floatfmt="{:.2f}")
    law_cols = [c for c in ranking.columns if c not in ("strategy", "label")]
    rank_tbl = md_table(
        ranking[["label"] + law_cols].rename(columns={"label": "Strategy"}),
        floatfmt="{:.0f}")

    if found["ordering_ever_changes"]:
        headline = (
            f"**The ranking is not invariant to the mortality assumption.** "
            f"The order of the strategies changes between the fixed horizon "
            f"and at least one of the laws swept, so results elsewhere in "
            f"this paper carry a dependence on dying at "
            f"{int(cfg['lifecycle']['age_death'])} that was not visible "
            f"before.")
    elif found["winner_ever_changes"]:
        headline = (
            "**The winner changes under a random lifespan**, which is the "
            "strongest form this check can fail in. The fixed horizon is "
            "doing work the rest of the paper attributes to the allocation.")
    else:
        headline = (
            f"**Nothing changes places.** Across a fixed horizon and "
            f"{found['laws'] - 1} mortality laws spanning expected death "
            f"ages from {found['shortest_life_expectancy']:.0f} to "
            f"{found['longest_life_expectancy']:.0f}, the ordering is "
            f"identical and the lead moves by at most "
            f"{found['largest_change_pp']:.2f} points from its "
            f"fixed-horizon value of {found['fixed_horizon_gap_pct']:.2f}%.")

    ruin_note = (
        "Outliving the portfolio becomes *less* likely under every law, which "
        "is not the portfolio getting safer: it is the investor having fewer "
        "years in which to outlive it. A fixed horizon of ninety-three is a "
        "pessimistic longevity assumption, and the ruin probabilities "
        "reported elsewhere in this paper inherit that pessimism."
        if found["ruin_falls_under_mortality"] else
        "Outliving the portfolio does not become uniformly less likely under "
        "the swept laws, which is worth noting: a shorter expected life "
        "reduces the years available to run out of money, so the opposite "
        "would have been the expected direction.")

    figure_list = "\n".join(f"* `{f}`" for f in figures)
    intro = _header(
        "24 - Death at a Random Age",
        "Every result before this section kills the investor on schedule at "
        f"{int(cfg['lifecycle']['age_death'])}.")

    body = f"""
## 1. Why a fixed horizon is not neutral

Dying with certainty at {int(cfg['lifecycle']['age_death'])} is a modelling
convenience, and `docs/04` already lists it as one of the differences from
the study this project re-implements. It distorts in two directions at once:

* it **understates** longevity risk, because nobody knows they have exactly
  {int(cfg['lifecycle']['age_death']) - int(cfg['lifecycle']['age_retire'])}
  retired years to fund; and
* it **overstates** the far tail, because a strategy is rewarded for
  consumption at ninety-two that most investors never live to spend.

## 2. How it is done here: re-weighting, not re-simulating

Under the headline withdrawal rule -- a fixed real fraction of wealth at
retirement -- the policy does not depend on the death age. A random lifespan
therefore changes only *which* years of an already-simulated path are
experienced and with what probability, which makes the exact treatment a
re-weighting of the utility aggregation:

```
U = sum_h beta^h S(h) u(c_h)
  + b * sum_h beta^(h+1) (S(h) - S(h+1)) u(kappa + W_(h+1))
  + b * beta^H S(H) u(kappa + W_H)
```

Consumption in year `h` is enjoyed only if the investor is alive; the estate
is whatever wealth is left in the year they die. A certain stream `c` paired
with bequest `c - kappa` still returns exactly `c`, so these certainty
equivalents are in the same units as every other one in the paper.

This is **exact** for any policy that does not condition on the death age --
the fixed real rule, the constant-percentage rule, every constant-weight
strategy. It is **approximate** for the horizon-based spending rules of
section #spending, which amortise over a planning horizon and would
themselves change if they knew the mortality table.

Survival follows a Gompertz law, the same functional form the actuarial
spending rule already uses as its planning divisor. It is a model, not a life
table lifted from data, so the calibration is swept rather than asserted.

## 3. The sweep

At γ = {gamma:g} over {int(notes['n_paths']):,} lifetimes:

{curve_tbl}

{headline}

{ruin_note}

## 4. Rank under each assumption

{rank_tbl}

## 5. What this changes

* {"The results elsewhere in this paper are not resting on the fixed horizon." if not found["ordering_ever_changes"] else "The results elsewhere in this paper carry a dependence on the fixed horizon, and the limitations section should say so."}
* The lead spans {found['min_gap_pct']:.2f}% to {found['max_gap_pct']:.2f}%
  across every assumption tested, against
  {found['fixed_horizon_gap_pct']:.2f}% at the fixed horizon.
* Ruin probabilities quoted elsewhere are computed against a certain
  ninety-third birthday. Under any of these laws they are **too high**, and
  the table above gives the size of the correction.
* **What is not modelled**: a couple rather than an individual, mortality
  correlated with wealth, and a policy that adapts to the mortality table.
  The last would raise every certainty equivalent here, so these numbers are
  a floor.

## 6. Figures

{figure_list}

## 7. Reproduction

```bash
python main.py --steps 24
```

Runtime {float(notes['elapsed_seconds']):.0f}s at {int(notes['n_paths']):,}
paths, γ = {gamma:g}. Tables in
`{cfg['run']['table_dir']}/mortality_*.csv`.
"""
    return _write(path, [intro, body])


def write_doc_25(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """What a means-tested pension does to a result solved under an American one."""
    gaps = frames["gaps"]
    entitlement = frames.get("entitlement", pd.DataFrame())
    replacement = frames.get("replacement", pd.DataFrame())
    gamma = float(notes["gamma"])
    found = notes["verdict"]
    params = notes["parameters"]

    gap_tbl = md_table(_compact(
        gaps, ["label", "best_lift_pct", "mean_lift_pct", "p5_lift_pct",
               "gap_pct", "winner"],
        {"label": "Pension system",
         "best_lift_pct": "CEC vs US (%)",
         "mean_lift_pct": "Mean vs US (%)",
         "p5_lift_pct": "5th pctile vs US (%)",
         "gap_pct": "All-intl over 50/50 (%)", "winner": "Best"}),
        floatfmt="{:.2f}")

    ent_tbl = ""
    if len(entitlement):
        # The profile is only informative for a system whose taper actually
        # bites. The zero-taper control pays everybody the full rate by
        # construction, and printing that as if it described the means test
        # would contradict the replacement table three rows below.
        available = list(dict.fromkeys(entitlement["system"]))
        key = next((k for k in ("australia_as_legislated",
                                "australia_non_homeowner",
                                "age_pension_matched") if k in available),
                   available[0])
        block = entitlement[entitlement["system"] == key]
        every_fifth = block[block["age"] % 5 == 0]
        ent_label = next((str(r["label"]) for _, r in gaps.iterrows()
                          if str(r["system"]) == key), key)
        ent_tbl = md_table(_compact(
            every_fifth, ["age", "share_full_rate", "share_part_rate",
                          "share_no_pension", "mean_pension_x_earnings"],
            {"age": "Age", "share_full_rate": "Full rate",
             "share_part_rate": "Part rate", "share_no_pension": "None",
             "mean_pension_x_earnings": "Mean pension (x avg earnings)"}),
            floatfmt="{:.3f}")

    rep_tbl = ""
    if len(replacement):
        rep_tbl = md_table(_compact(
            replacement, ["label", "mean_pension",
                          "pension_share_of_consumption"],
            {"label": "System", "mean_pension": "Mean pension",
             "pension_share_of_consumption": "Share of retirement "
                                             "consumption"}),
            floatfmt="{:.3f}")

    if found["mean_and_cec_disagree"]:
        headline = (
            f"**The Australian system raises the average and lowers the "
            f"certainty equivalent.** As legislated it delivers "
            f"{found['australia_mean_lift_pct']:+.1f}% mean retirement "
            f"consumption against the American baseline and "
            f"{found['australia_lift_pct']:+.1f}% certainty-equivalent "
            f"consumption, because the fifth percentile falls "
            f"{found['australia_p5_lift_pct']:+.1f}%. Compulsory saving buys "
            f"a bigger portfolio; the means test removes the floor that "
            f"portfolio would have sat on. Crossing the two features "
            f"separates them: the contribution rate alone is worth "
            f"{found['extra_saving_lift_pct']:+.1f}%, and the assets test is "
            f"what takes it back.")
    elif found["australia_delivers_more"]:
        headline = (
            f"**The Australian system delivers more retirement consumption**, "
            f"{found['australia_lift_pct']:+.1f}% on the certainty equivalent "
            f"and {found['australia_mean_lift_pct']:+.1f}% on the mean. The "
            f"compulsory contribution outweighs what the means test claws "
            f"back.")
    else:
        headline = (
            f"**The Australian system delivers less**, "
            f"{found['australia_lift_pct']:+.1f}% on the certainty equivalent "
            f"and {found['australia_mean_lift_pct']:+.1f}% on the mean. The "
            f"Superannuation Guarantee does not buy back what the loss of an "
            f"unconditional pension costs.")
    if found["winner_ever_changes"]:
        headline += (
            f"\n\n**The ranking is not the same under every regime.** The "
            f"best strategy varies across the sweep "
            f"({', '.join(found['winners_seen'])}), which means applying one "
            f"country's schedule to sixteen was not an innocent "
            f"simplification. Which regime a reader sits in depends on "
            f"whether their balance clears the assets-test cut-out.")

    ent_tbl_label = locals().get("ent_label", "")
    figure_list = "\n".join(f"* `{f}`" for f in figures)
    intro = _header(
        "25 - A Pension System That Is Not the American One",
        "Sixteen countries, one country's social security. Australia is the "
        "natural test because it is built on the opposite principle.")

    body = f"""
## 1. The assumption being relaxed

Every result in this paper puts the same public pension behind all sixteen
countries: the US primary-insurance-amount formula, progressive in career
earnings, paid in full regardless of what else the retiree owns. It is the
schedule of exactly one country in the panel, and the panel's whole point is
that countries differ.

It is also the *shape* most flattering to the argument. An earnings-related
pension is a bond-like endowment: it arrives whatever the portfolio does, so
it crowds fixed income out of the financial portfolio and pushes the optimal
equity share up. A pension withdrawn as private wealth rises would run the
logic backwards.

Australia is the developed world's counter-example on both counts. The Age
Pension is flat rather than earnings-related, and it is **means-tested**:
assessable assets above a free area reduce it on a taper steep enough to work
as a wealth tax, until it cuts out entirely. Retirement saving is separately
compulsory through the Superannuation Guarantee, 12% of ordinary time
earnings since 1 July 2025.

## 2. Calibration

Rates are held as multiples of economy-wide average earnings so the schedule
travels across the panel's currencies. Against Australian Average Weekly
Ordinary Time Earnings for full-time adults of $2,051.10 a week (ABS,
November 2025; $106,657 a year):

| Quantity | Statutory | In average earnings |
| --- | --- | --- |
| Maximum single rate | $1,200.90/fortnight | {params['pension_full_rate']:.3f} |
| Assets-test free area | $321,500 | {params['pension_free_area']:.3f} |
| Taper | $3/fortnight per $1,000 | {params['pension_taper']:.3f} a year |
| Cut-out | $722,000 | {params['pension_free_area'] + params['pension_full_rate'] / params['pension_taper']:.3f} |

Single homeowner, March 2026 indexation, assets-test thresholds from July
2026.

**The means test is applied year by year, not once.** An earnings-related
benefit can be settled at retirement from career average earnings. A means
test cannot: it is assessed on assets as they stand, so it is recomputed at
every retirement year as the portfolio draws down. That is the mechanism
worth watching, and it is why the entitlement profile below moves with age.

**The guarantee is a second contribution stream, not a larger first one.**
The worker still saves the paper's own
{float(cfg['lifecycle']['savings_rate']):.0%} out of take-home pay; the
employer pays 12% of ordinary time earnings on top, 15% is taken as
contributions tax, and the remaining 10.2% is invested in the same strategy
and assessed by the same means test. Total contributions are 20.2% of income
against the American saver's 10%. Both pots hold the same strategy and face
no differential tax on earnings here, so they are financially one pot and are
simulated as one.

Working-life consumption is unchanged by the guarantee, because its statutory
incidence is on the employer. If the true incidence is on workers through
lower wages -- which is what most of the empirical literature finds -- an
Australian is paying for it in forgone pay and the comparison is generous to
them by that amount. It does not touch the certainty equivalents, because the
utility window here is retirement only; it does mean this compares *systems
as legislated* rather than two workers with the same lifetime resources,
which is why the matched-contribution rows are there.

**Why the sweep crosses two features.** Australia differs from America in the
pension's shape *and* in the contribution rate, and they push in opposite
directions: the taper compresses outcomes and can reorder them, while a
higher contribution rate raises everything and pushes retirees past the
cut-out where the taper stops biting. A single Australia-versus-America row
would confound the two.

## 3. What changes

{gap_tbl}

{headline}

## 4. Is the taper doing any work?

A means test that never binds is a flat pension in disguise; one that always
binds to zero is no pension at all. Neither would tell a reader anything, so
the entitlement profile is the first thing to check.

Under *{ent_tbl_label}*:

{ent_tbl}

{rep_tbl}

## 5. What this changes

* The headline gap spans {found['min_gap_pct']:.2f}% to
  {found['max_gap_pct']:.2f}% across the {found['systems']} regimes, against
  {found['baseline_gap_pct']:.2f}% under the American schedule the rest of
  the paper uses.
* Certainty-equivalent retirement consumption moves
  {found['australia_lift_pct']:+.1f}% under the system as legislated, which
  is further than any parameter swept anywhere else in this project moves it.
* The extra contribution on its own is worth
  {found['extra_saving_lift_pct']:+.1f}%; the means test at the baseline
  contribution rate is worth {found['means_test_lift_pct']:+.1f}%.
* {"The ranking is identical under every regime." if found['ranking_identical_everywhere'] else f"The full ranking is not identical everywhere: {found['n_rankings']} distinct orderings appear across the {found['systems']} regimes."}
* {"The lead stays positive under every regime tested." if found['gap_positive_everywhere'] else "The lead does not survive every regime, and the limitations section should say which."}
* **What is not modelled**: the income test (deeming), which for a retiree
  whose assets are mostly superannuation is not the binding one but is an
  assumption rather than a theorem; the family home's exemption from the
  assets test, which is the largest single feature of the real system and is
  absent because housing is absent from the baseline model; and
  superannuation's tax treatment, in a paper that models no taxes anywhere.
  The sweep brackets the last of these by carrying both the statutory 12% and
  the 10.2% that survives the contributions tax.

## 6. Figures

{figure_list}

## 7. Reproduction

```bash
python main.py --steps 25
```

Runtime {float(notes['elapsed_seconds']):.0f}s at {int(notes['n_paths']):,}
paths, γ = {gamma:g}. Tables in
`{cfg['run']['table_dir']}/pension_*.csv`.
"""
    return _write(path, [intro, body])


def write_doc_26(
    path: str | Path,
    cfg: Mapping[str, Any],
    frames: Mapping[str, pd.DataFrame],
    figures: Sequence[str],
    notes: Mapping[str, Any],
) -> Path:
    """What the solved schedule costs to trade, and whether it can afford it."""
    measured = frames["measured"]
    curve = frames["curve"]
    gamma = float(notes["gamma"])
    found = notes["verdict"]
    cross = notes["cross"]

    turn_tbl = md_table(_compact(
        measured, ["label", "turnover_total", "turnover_drift_only",
                   "turnover_schedule_only", "excess_over_drift",
                   "lifetime_turnover"],
        {"label": "Strategy", "turnover_total": "Traded a year",
         "turnover_drift_only": "Drift alone",
         "turnover_schedule_only": "Schedule alone",
         "excess_over_drift": "Excess over drift",
         "lifetime_turnover": "Over a lifetime"}), floatfmt="{:.4f}")

    cost_tbl = md_table(_compact(
        curve, ["basis_points", "gap_pct", "winner"],
        {"basis_points": "One-way cost (bp)",
         "gap_pct": "Solved over best fixed (%)", "winner": "Best"}),
        floatfmt="{:.2f}")

    be = found["break_even_bp"]
    if found["survives_whole_grid"]:
        headline = (
            f"**The solved schedule pays for its own trading.** Its lead over "
            f"the best fixed portfolio starts at "
            f"{found['baseline_gap_pct']:.2f}% and is still "
            f"{found['gap_at_highest_pct']:.2f}% at "
            f"{found['highest_cost_bp']:.0f} basis points a trade -- a cost no "
            f"index investor pays and several times what a retail platform "
            f"charges. The optimisation sections were not spending money they "
            f"did not have.")
    elif be > 10.0:
        headline = (
            f"**The solved schedule survives realistic trading costs but not "
            f"unlimited ones.** Its lead of {found['baseline_gap_pct']:.2f}% "
            f"reaches zero at {be:.1f} basis points one-way. That is well "
            f"above an index fund's spread and comfortably above a large "
            f"platform's brokerage, so the result stands; it is not so far "
            f"above that a hand-traded portfolio of small parcels could "
            f"ignore it.")
    else:
        headline = (
            f"**Trading costs eat the solved schedule's edge.** Its lead of "
            f"{found['baseline_gap_pct']:.2f}% is gone by {be:.1f} basis "
            f"points one-way, which is inside what a real investor pays. The "
            f"advantage measured in the optimisation sections is therefore "
            f"partly an artefact of a frictionless rebalance, and should be "
            f"read as an upper bound.")

    if cross.get("measured"):
        cross_note = (
            f"The solved schedule turns over "
            f"{cross['solved_turnover'] * 100:.2f}% of the portfolio a year. "
            + ("The benchmark it is measured against is a single-asset "
               "portfolio, which never drifts away from itself and so never "
               "rebalances at all: it trades nothing, ever."
               if cross.get("fixed_trades_nothing") else
               f"The fixed comparison turns over "
               f"{cross['fixed_turnover'] * 100:.2f}% -- "
               f"{cross['ratio']:.2f} times less, or "
               f"{cross['extra_turnover'] * 100:+.2f} points of extra trading "
               f"a year."))
        if cross.get("solved_is_self_rebalancing"):
            cross_note += (
                " It trades *less* than a portfolio pinned to last year's "
                "weights would have, which is the self-rebalancing effect: "
                "the schedule's move runs with the drift rather than against "
                "it, and a naive turnover count would have missed it.")
    else:
        cross_note = ("The solved schedule was not available in this run, so "
                      "the comparison falls back to the fixed strategies.")

    figure_list = "\n".join(f"* `{f}`" for f in figures)
    intro = _header(
        "26 - What the Schedule Costs to Trade",
        "The optimiser chose a different portfolio every year and was never "
        "charged for the trade.")

    body = f"""
## 1. The objection

Section 12 of this project prices the expense ratio and finds the fee
differential that would undo the headline. It says nothing about the other
cost of running a portfolio, which is trading it, and the omission lands
hardest on the part of the paper most exposed to it. A fixed 50/50 portfolio
trades because its assets drifted apart. A schedule solved age by age over
the whole weight simplex trades for that reason *and* because it decided to
hold something different this year -- and the optimiser that chose the
difference paid nothing for it.

## 2. Measuring the trade

Turnover is reported one-way: half the sum of absolute weight changes, so
selling one asset to buy another counts once. It is split three ways.

* **Total** -- the trade actually required each year, on simulated paths.
* **Drift** -- what a portfolio holding last year's weights would have had to
  trade anyway. This is the floor no schedule can get under.
* **Schedule** -- the deterministic move the target makes between two ages:
  what following the plan would cost in a world where nothing ever drifted.

{turn_tbl}

{cross_note}

The three columns do not add up, and the reason is worth stating. A schedule
that cuts equity in a year equity outperformed is trading *with* the drift
rather than against it, so its total can sit below its drift counterfactual.
A glide path is partly self-rebalancing, which is a point in its favour that
a naive turnover count would miss.

## 3. Charging for it

The cost is proportional to the value turned over and is taken at the
rebalance, before that year's return compounds on what is left. Every
strategy pays it on the same paths, so the question is never whether costs
hurt -- they hurt everyone -- but which portfolio they hurt more.

{cost_tbl}

{headline}

## 4. What this changes

* Break-even one-way trading cost: **{"never reached on this grid" if found['survives_whole_grid'] else f"{be:.1f} basis points"}**.
* Busiest strategy: {found['busiest_strategy']} at
  {found['busiest_turnover'] * 100:.2f}% a year. Quietest:
  {found['quietest_strategy']} at {found['quietest_turnover'] * 100:.2f}%.
* {"The best strategy is the same at every cost tested." if not found['winner_ever_changes'] else f"The best strategy changes across the cost grid: {', '.join(found['winners_seen'])}."}
* **What is not modelled**: costs are proportional and symmetric, with no
  bid-ask asymmetry, no market impact and no minimum ticket. Contributions
  during accumulation are invested pro-rata rather than steered toward the
  underweight asset, which overstates turnover for a real saver making
  regular contributions -- so the break-even here is, if anything, reached
  too easily. Tax on realised gains is a cost of trading in a taxable
  account and is absent, along with every other tax in this paper.

## 5. Figures

{figure_list}

## 6. Reproduction

```bash
python main.py --steps 26
```

Runtime {float(notes['elapsed_seconds']):.0f}s at {int(notes['n_paths']):,}
paths, γ = {gamma:g}. Tables in
`{cfg['run']['table_dir']}/turnover_*.csv`.
"""
    return _write(path, [intro, body])
